import React, { useState, useEffect } from 'react';
import {
  Container, Row, Col, Card, CardBody, CardHeader, Button, FormGroup, Label, Input, Modal, ModalHeader, ModalBody, ModalFooter, ListGroup, ListGroupItem, Spinner,
} from 'reactstrap';
import styled from 'styled-components';
import { FaSearch, FaFilter, FaInfoCircle, FaSave, FaBan, FaSyncAlt, FaFileExport, FaPrint, FaDollarSign, FaPercent, FaStickyNote, FaTruck } from 'react-icons/fa';
import { loadOrders, addOrderNote, finalizeOrder, updateOrderStatus, loadProfile } from '../auth/api';
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import currencyFormatter from 'currency-formatter';

// Styled Components
const StyledContainer = styled.div`
  padding: 2rem;
  background-color: #f5f5f5;
  min-height: calc(100vh - 40px - 100px);
  max-height: calc(100vh - 40px - 100px);
`;


const GradientCard = styled(Card)`
  margin-bottom: 20px;
  border-radius: 10px;
  background: linear-gradient(135deg, #003459, #007ea7);
  color: white;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
`;

const SectionTitle = styled(CardHeader)`
  background: linear-gradient(45deg, #00507d, #00293c);
  color: #ffffff;
  font-size: 1.25rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  svg {
    margin-right: 10px;
  }
`;

const BoldText = styled.span`
  font-weight: bold;
`;

const OnlineOrderManagement = () => {
  const [orders, setOrders] = useState([]);
  const [filteredOrders, setFilteredOrders] = useState([]);
  const [selectedOrder, setSelectedOrder] = useState(null);
  const [statusFilter, setStatusFilter] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [note, setNote] = useState('');
  const [modal, setModal] = useState(false);
  const [noteModal, setNoteModal] = useState(false);
  const [discount, setDiscount] = useState({ value: '0', type: 'amount' });
  const [surcharge, setSurcharge] = useState({ value: '0', type: 'amount' });
  const [taxPercentage, setTaxPercentage] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false); // State for processing
  const [showDeliverySubPage, setShowDeliverySubPage] = useState(false); // New state for Delivery Subpage

  const [currency, setCurrency] = useState('USD');
  useEffect(() => {
    const fetchProfile = async () => {
      const profile = await loadProfile();
      setCurrency(profile.currency || 'USD'); // Default to USD if no currency is set
    };
    fetchProfile();
  }, []);

  
  // Fetch profile data and set it
  /*
  useEffect(() => {
    const fetchProfileData = async () => {
      const profile = await loadProfile();
      setProfileData(profile);
    };
    fetchProfileData();
  }, []);
  */

  useEffect(() => {

    let timeout;

    const fetchOrders = async () => {

      timeout = setTimeout(async () => {
      const fetchedOrders = await loadOrders();
      if (Array.isArray(fetchedOrders)) {
        const formattedOrders = fetchedOrders.map(order => ({
          ...order,
          status: typeof order.status === 'object' ? JSON.stringify(order.status) : order.status,
          notes: Array.isArray(order.notes) ? order.notes : [], // Ensure notes is an array
        }));
        setOrders(formattedOrders);
        setFilteredOrders(formattedOrders);

        
        
      } else {
        setOrders([]);
        setFilteredOrders([]);
      }

    }, 300); 
    };

    // Fetch orders initially and after every API call
    fetchOrders();
    const intervalId = setInterval(fetchOrders, 5000); // Fetch orders every 5 seconds
    return () => clearInterval(intervalId); // Cleanup interval on component unmount
  }, [orders]);

  const toggleModal = () => {
    setModal(!modal);
  };

  const toggleNoteModal = () => {
    setNoteModal(!noteModal);
  };

  const handleFilterChange = (e) => {
    const filter = e.target.value;
    setStatusFilter(filter);
    filterOrders(searchQuery, filter);
  };

  const handleSearchChange = (e) => {
    const query = e.target.value;
    setSearchQuery(query);
    filterOrders(query, statusFilter);
  };

  const filterOrders = (query, filter) => {
    let result = orders;

    if (query) {
      result = result.filter(order =>
        order.customerName.toLowerCase().includes(query.toLowerCase()) ||
        order.invoiceNumber.includes(query)
      );
    }
    if (filter) {
      result = result.filter(order => order.status.toLowerCase() === filter.toLowerCase());
    }

    setFilteredOrders(result);
  };

  const selectOrder = (order) => {
    setSelectedOrder(order);
    toggleModal();
  };

  const getNextAndPreviousStates = (currentStatus) => {
    const states = ['Pending', 'In Progress', 'Shipped', 'Delivered'];
    const currentIndex = states.indexOf(currentStatus);
    return {
      previous: currentIndex > 0 ? states[currentIndex - 1] : null,
      next: currentIndex < states.length - 1 ? states[currentIndex + 1] : null
    };
  };

  const ProcessingModal = () => (
    /*
    <Modal isOpen={true}>
      <ModalHeader>Processing</ModalHeader>
      <ModalBody>
        <p>Please wait while the action is being processed...</p>
      </ModalBody>
    </Modal>
    */
    <Modal isOpen={true}>
    <ModalBody className="text-center">
      <Spinner color="primary" />
      <p>Processing your request...</p>
    </ModalBody>
  </Modal>
   
  );

  const handleStatusChange = async (newStatus) => {
    setIsProcessing(true); // Show processing modal
    const currentStatus = selectedOrder.status;
  
    try {
      const allowedTransitions = {
        'Cancelled': ['Pending']
      };
  
      if (currentStatus === 'Cancelled' && !allowedTransitions['Cancelled'].includes(newStatus)) {
        alert("A canceled order can only be moved back to 'Pending'.");
        setIsProcessing(false); // Hide processing modal
        return;
      }
  
      const updatedOrder = { ...selectedOrder, status: newStatus };
  
      // Update order status on server
      const updatedFromServer = await updateOrderStatus(updatedOrder.invoiceNumber, newStatus);
  
      // Add status change note
      const statusChangeNote = {
        text: `Status changed from ${currentStatus} to ${newStatus}.`,
        timestamp: new Date().toISOString(),
      };
      await addOrderNote(updatedFromServer.invoiceNumber, statusChangeNote);
  
      // Create new arrays by replacing the updated order
      const updatedOrders = orders.map(order =>
        order.invoiceNumber === updatedFromServer.invoiceNumber ? updatedFromServer : order
      );
  
      const updatedFilteredOrders = filteredOrders.map(order =>
        order.invoiceNumber === updatedFromServer.invoiceNumber ? updatedFromServer : order
      );
  
      // Update the state with new arrays
      setOrders([...updatedOrders]);
      setFilteredOrders([...updatedFilteredOrders]);
      setSelectedOrder(updatedFromServer); // Also update the currently selected order
    } catch (error) {
      console.error("Error updating order status:", error);
    } finally {
      setIsProcessing(false); // Hide processing modal
      setModal(false);
    }
  };
  

  const handleAddToSales = async () => {
    setIsProcessing(true); // Show processing modal


    if (selectedOrder) {

      let total = selectedOrder.cart.reduce(
        (sum, item) => sum + item.price * item.quantity,
        0
      ).toFixed(2);
  
      if (discount.type === 'percentage') {
        total -= (total * discount.value) / 100;
      } else {
        total -= parseFloat(discount.value || 0);
      }
  
      if (surcharge.type === 'percentage') {
        total += (total * surcharge.value) / 100;
      } else {
        total += parseFloat(surcharge.value || 0);
      }

      let gstAmount = selectedOrder.cart.reduce((sum, item) => {
        // Calculate GST for each product based on its tax percentage or the default tax percentage
        const productGST = (item.price * item.quantity * (item.taxPercentage || 0)) / 100;
        return sum + productGST;
      }, 0);
    
      total += parseFloat(gstAmount);
      const updatedOrder = { ...selectedOrder, 
                                txn_type: 'Online Sale', 
                                taxAmount:parseFloat(gstAmount).toFixed(2)  };
      await finalizeOrder(updatedOrder.invoiceNumber, updatedOrder);

      setOrders(orders.filter(order => order.invoiceNumber !== updatedOrder.invoiceNumber));
      setFilteredOrders(filteredOrders.filter(order => order.invoiceNumber !== updatedOrder.invoiceNumber));
      toggleModal();
    }
    setIsProcessing(false); // Hide processing modal
  };

  const handleNoteSave = async () => {
    setIsProcessing(true); // Show processing modal
    if (!selectedOrder || !selectedOrder.invoiceNumber) {
      setIsProcessing(false); // Hide processing modal
      return;
    }
    const newNote = {
      text: note,
      timestamp: new Date().toISOString(),
    };
    await addOrderNote(selectedOrder.invoiceNumber, newNote);
    setNote('');
    toggleNoteModal();
    toggleModal();
    setIsProcessing(false); // Hide processing modal
  };

  const exportToExcel = () => {
    const worksheet = XLSX.utils.json_to_sheet(filteredOrders);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Orders');
    XLSX.writeFile(workbook, 'Orders.xlsx');
  };

  const toggleDiscountType = () => {
    setDiscount({
      ...discount,
      type: discount.type === 'amount' ? 'percentage' : 'amount',
    });
  };

  const toggleSurchargeType = () => {
    setSurcharge({
      ...surcharge,
      type: surcharge.type === 'amount' ? 'percentage' : 'amount',
    });
  };

  const calculateTotal = () => {
    let total = selectedOrder.cart.reduce(
      (sum, item) => sum + item.price * item.quantity,
      0
    ).toFixed(2);

    if (discount.type === 'percentage') {
      total -= (total * discount.value) / 100;
    } else {
      total -= parseFloat(discount.value || 0);
    }

    if (surcharge.type === 'percentage') {
      total += (total * surcharge.value) / 100;
    } else {
      total += parseFloat(surcharge.value || 0);
    }

    let gstAmount = selectedOrder.cart.reduce((sum, item) => {
      // Calculate GST for each product based on its tax percentage or the default tax percentage
      const productGST = (item.price * item.quantity * (item.taxPercentage || 0)) / 100;
      return sum + productGST;
    }, 0);

    total += parseFloat(total + gstAmount);
    return parseFloat(total).toFixed(2);
  };

  
  


  const toggleDeliverySubPage = () => setShowDeliverySubPage(!showDeliverySubPage); // Toggle for Delivery Subpage

  return (
    <StyledContainer>
      {isProcessing && <ProcessingModal />} {/* Show processing modal if processing */}
      <Row>
        <Col md={12}>
          <Button color="info" onClick={toggleDeliverySubPage}><FaTruck /> Manage Deliveries</Button>
          {!showDeliverySubPage ? (
            <GradientCard>
              <SectionTitle>
                <FaSyncAlt /> Online Order Management
              </SectionTitle>
              <CardBody>
                <Row className="mb-3">
                  <Col md={6}>
                    <FormGroup>
                      <Label for="search"><FaSearch /> Search Orders</Label>
                      <Input
                        type="text"
                        id="search"
                        value={searchQuery}
                        onChange={handleSearchChange}
                        placeholder="Search by customer name or invoice number"
                      />
                    </FormGroup>
                  </Col>
                  <Col md={3}>
                    <FormGroup>
                      <Label for="statusFilter"><FaFilter /> Filter by Status</Label>
                      <Input type="select" id="statusFilter" value={statusFilter} onChange={handleFilterChange}>
                        <option value="">All</option>
                        <option value="Pending">Pending</option>
                        <option value="In Progress">In Progress</option>
                        <option value="Shipped">Shipped</option>
                        <option value="Delivered">Delivered</option>
                        <option value="Cancelled">Cancelled</option>
                      </Input>
                    </FormGroup>
                  </Col>
                  <Col md={3} className="text-right">
                    <Button color="info" onClick={exportToExcel}><FaFileExport /> Export Orders</Button>
                  </Col>
                </Row>
                <ListGroup>
                  {filteredOrders.length > 0 ? filteredOrders.map(order => (
                    <ListGroupItem key={order.invoiceNumber} className="d-flex justify-content-between align-items-center">
                      <span>
                        <strong>{order.customerName}</strong> - ${order.total ? order.total.toFixed(2) : '0.00'} - <BoldText>{order.status}</BoldText>
                      </span>
                      <Button color="primary" onClick={() => selectOrder(order)}><FaInfoCircle /> View Details</Button>
                    </ListGroupItem>
                  )) : <p>No orders found.</p>}
                </ListGroup>
              </CardBody>
            </GradientCard>
          ) : (
            <DeliverySubPage orders={orders} toggleMainPage={toggleDeliverySubPage} />
          )}
        </Col>
      </Row>

      {selectedOrder && (
        <Modal isOpen={modal} toggle={toggleModal}>
          <ModalHeader toggle={toggleModal}>Order Details - {selectedOrder.invoiceNumber}</ModalHeader>
          <ModalBody>
            <p><strong>Customer Name:</strong> {selectedOrder.customerName}</p>
            <p><strong>Address:</strong> {selectedOrder.address}</p> {/* Added address here */}
            <p><strong>Phone:</strong> {selectedOrder.customerPhone}</p>
            <p><strong>Total Amount:</strong> ${selectedOrder.total ? selectedOrder.total.toFixed(2) : '0.00'}</p>
            <p><strong>Order Status:</strong> <BoldText>{selectedOrder.status}</BoldText></p>
            <p><strong>Items Ordered:</strong></p>
            <ul>
              {selectedOrder.cart.map(item => (
                <li key={item.id}>{item.name} - {currencyFormatter.format(item.price.toFixed(2), { code: currency })} x {item.quantity}</li>
              ))}
            </ul>

            <FormGroup>
              <Row form>
                <Col xs="4">
                  <Label for="discount">Discount</Label>
                </Col>
                <Col xs="4">
                  <Input
                    type="number"
                    name="discount"
                    id="discount"
                    value={discount.value}
                    onChange={(e) =>
                      setDiscount({ ...discount, value: e.target.value })
                    }
                  />
                </Col>
                <Col xs="4">
                  <Button onClick={toggleDiscountType}>
                    {discount.type === 'amount' ? <FaDollarSign /> : <FaPercent />}
                  </Button>
                </Col>
              </Row>
            </FormGroup>
            <FormGroup>
              <Row form>
                <Col xs="4">
                  <Label for="surcharge">Surcharge</Label>
                </Col>
                <Col xs="4">
                  <Input
                    type="number"
                    name="surcharge"
                    id="surcharge"
                    value={surcharge.value}
                    onChange={(e) =>
                      setSurcharge({ ...surcharge, value: e.target.value })
                    }
                  />
                </Col>
                <Col xs="4">
                  <Button onClick={toggleSurchargeType}>
                    {surcharge.type === 'amount' ? <FaDollarSign /> : <FaPercent />}
                  </Button>
                </Col>
              </Row>
            </FormGroup>
            <p><strong>Subtotal:</strong> {currencyFormatter.format(selectedOrder.cart.reduce((sum, item) => sum + item.price * item.quantity, 0).toFixed(2), { code: currency })}</p>
            <FormGroup>
              <Row form>
                <Col xs="4">
                  <Label for="surcharge">GST</Label>
                </Col>
                <Col xs="4">
                  {selectedOrder.cart.reduce((sum, item) => {
                        // Calculate GST for each product based on its tax percentage or the default tax percentage
                        const productGST = (item.price * item.quantity * (item.taxPercentage || 0)) / 100;
                        return sum + productGST;
                      }, 0)
                      }
                </Col>
                <Col xs="4">
                  <Button onClick={toggleSurchargeType}>
                     <FaPercent />
                  </Button>
                </Col>
              </Row>
            </FormGroup>
            <p><strong>Total:</strong> ${calculateTotal()}</p>

            <Button color="primary" onClick={toggleNoteModal}><FaStickyNote /> Add Note</Button>
            {selectedOrder.notes && selectedOrder.notes.length > 0 && (
              <div className="mt-3">
                <h5>Notes</h5>
                <ListGroup>
                  {selectedOrder.notes.map((note, index) => (
                    <ListGroupItem key={index}>
                      {note.timestamp}: {note.text}
                    </ListGroupItem>
                  ))}
                </ListGroup>
              </div>
            )}
          </ModalBody>
          <ModalFooter>
            {getNextAndPreviousStates(selectedOrder.status).previous && (
              <Button color="secondary" onClick={() => handleStatusChange(getNextAndPreviousStates(selectedOrder.status).previous)}>
                <FaSyncAlt /> {getNextAndPreviousStates(selectedOrder.status).previous}
              </Button>
            )}
            {getNextAndPreviousStates(selectedOrder.status).next && (
              <Button color="primary" onClick={() => handleStatusChange(getNextAndPreviousStates(selectedOrder.status).next)}>
                <FaSyncAlt /> {getNextAndPreviousStates(selectedOrder.status).next}
              </Button>
            )}
            {selectedOrder.status !== 'Cancelled' && (
              <Button color="danger" onClick={() => handleStatusChange('Cancelled')}><FaBan /> Cancel Order</Button>
            )}
            {selectedOrder.status === 'Delivered' && (
              <Button color="success" onClick={handleAddToSales}><FaSave /> Add to Sales</Button>
            )}
            {selectedOrder.status === 'Cancelled' && (
              <Button color="danger" onClick={() => handleStatusChange('Pending')}><FaBan /> Move to Pending</Button>
            )}
            <Button color="secondary" onClick={toggleModal}>Close</Button>
          </ModalFooter>
        </Modal>
      )}

      <Modal isOpen={noteModal} toggle={toggleNoteModal}>
        <ModalHeader toggle={toggleNoteModal}>Add Note</ModalHeader>
        <ModalBody>
          <FormGroup>
            <Label for="note">Note</Label>
            <Input
              type="textarea"
              name="note"
              id="note"
              value={note}
              onChange={(e) => setNote(e.target.value)}
            />
          </FormGroup>
        </ModalBody>
        <ModalFooter>
          <Button color="primary" onClick={handleNoteSave}><FaSave /> Save Note</Button>
          <Button color="secondary" onClick={toggleNoteModal}>Cancel</Button>
        </ModalFooter>
      </Modal>
    </StyledContainer>
  );
};

// DeliverySubPage Component (New addition)
const DeliverySubPage = ({ orders, toggleMainPage }) => {
  const [deliveryDetails, setDeliveryDetails] = useState({ route: '', distance: '', expense: '' });

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setDeliveryDetails({ ...deliveryDetails, [name]: value });
  };

  const handleDeliverySubmit = (orderId) => {
    console.log(`Order ID: ${orderId} | Route: ${deliveryDetails.route}, Distance: ${deliveryDetails.distance}, Expense: ${deliveryDetails.expense}`);
    alert(`Delivery info saved for Order ID: ${orderId}`);
  };

  return (
    <Container>
      <Row>
        <Col md={12}>
          <Card>
            <CardHeader>Delivery Management</CardHeader>
            <CardBody>
              {orders.filter(order => order.status === 'Delivered').map(order => (
                <ListGroupItem key={order.invoiceNumber}>
                  <p><strong>Order ID:</strong> {order.invoiceNumber}</p>
                  <FormGroup>
                    <Label for="route">Route</Label>
                    <Input type="text" name="route" value={deliveryDetails.route} onChange={handleInputChange} />
                  </FormGroup>
                  <FormGroup>
                    <Label for="distance">Distance (km)</Label>
                    <Input type="number" name="distance" value={deliveryDetails.distance} onChange={handleInputChange} />
                  </FormGroup>
                  <FormGroup>
                    <Label for="expense">Additional Expense</Label>
                    <Input type="number" name="expense" value={deliveryDetails.expense} onChange={handleInputChange} />
                  </FormGroup>
                  <Button color="primary" onClick={() => handleDeliverySubmit(order.invoiceNumber)}>Save Delivery Info</Button>
                </ListGroupItem>
              ))}
            </CardBody>
            <Button color="danger" onClick={toggleMainPage}>Back to Order Management</Button>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default OnlineOrderManagement;
