import React, { useState, useEffect, useRef } from 'react';
import {
  Container, Button, ListGroup, ListGroupItem, Form, FormGroup,
  Label, Input, Card, CardBody, CardTitle, CardText, Modal, ModalHeader, ModalBody, ModalFooter
} from 'reactstrap';
import styled, { keyframes } from 'styled-components';
import axios from 'axios';
import { loadProducts, loadCart, saveCart, createOrder } from './api';
import CustomerFooter from './CustomerFooter';
import { useDraggable } from 'react-use-draggable-scroll';

const theme = {
  primary: '#00507d',
  secondary: '#007ea7',
  accent: '#f5a623',
  background: '#f4f4f9',
  text: '#333',
  cartBackground: '#ffffff',
  cartBorder: '#ccc',
  cartText: '#333',
};

const fadeIn = keyframes`
  from { opacity: 0; }
  to { opacity: 1; }
`;

const scaleIn = keyframes`
  from { transform: scale(0.95); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
`;

const StyledContainer = styled(Container)`
  padding-top: 2rem;
  padding-bottom: 2rem;
  animation: ${fadeIn} 0.5s ease-in-out;
`;

const SectionContainer = styled(Container)`
  padding-top: 2rem;
  padding-bottom: 2rem;
  animation: ${fadeIn} 0.5s ease-in-out;
`;

const AddressSection = styled.div`
  padding: 20px;
  margin-bottom: 20px;
  border: 1px solid ${theme.primary};
  border-radius: 10px;
  background-color: #e6f2ff;
`;

const AddressLabel = styled(Label)`
  font-weight: bold;
  color: ${theme.primary};
`;

const PrimaryButton = styled(Button)`
  background-color: ${theme.primary};
  border-color: ${theme.primary};
  transition: background-color 0.3s ease, transform 0.2s ease;

  &:hover {
    background-color: ${theme.secondary};
    transform: translateY(-2px);
  }

  &:disabled {
    background-color: ${theme.primary}80;
  }
`;

const ProductDetailsModal = ({ product, isOpen, toggle }) => (
  <Modal isOpen={isOpen} toggle={toggle}>
    <ModalHeader toggle={toggle}>{product?.name}</ModalHeader>
    <ModalBody>
      <p><strong>Price:</strong> ₹{parseFloat(product?.price || 0).toFixed(2)}</p>
      <p>{product?.description}</p>
    </ModalBody>
  </Modal>
);

const MiniCartContainer = styled.div`
  position: fixed;
  bottom: 20px;
  right: 20px;
  width: 300px;
  background-color: ${theme.cartBackground};
  border: 1px solid ${theme.cartBorder};
  border-radius: 10px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  z-index: 1000;
  cursor: grab;
  padding: 15px;
`;

const MiniCartHeader = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
`;

const MiniCartTitle = styled.h5`
  margin: 0;
  color: ${theme.cartText};
`;

const MiniCartToggle = styled(Button)`
  background-color: ${theme.accent};
  border: none;
  padding: 5px 10px;
  font-size: 12px;
  border-radius: 20px;
`;

const MiniCartContent = styled.div`
  display: ${({ isMinimized }) => (isMinimized ? 'none' : 'block')};
`;

const MiniCart = ({ cart, updateQuantity, proceedToCartReview }) => {
  const [isMinimized, setIsMinimized] = useState(false);
  const miniCartRef = useRef(null);

  useDraggable(miniCartRef);

  const toggleCart = () => {
    setIsMinimized(!isMinimized);
  };

  const calculateTotalItems = () => {
    return cart.reduce((sum, item) => sum + item.quantity, 0);
  };

  const calculateTotalPrice = () => {
    return cart.reduce((sum, item) => sum + parseFloat(item.price) * item.quantity, 0).toFixed(2);
  };

  return (
    <MiniCartContainer ref={miniCartRef}>
      <MiniCartHeader>
        <MiniCartTitle>Cart ({calculateTotalItems()})</MiniCartTitle>
        <MiniCartToggle onClick={toggleCart}>
          {isMinimized ? 'Expand' : 'Minimize'}
        </MiniCartToggle>
      </MiniCartHeader>
      <MiniCartContent isMinimized={isMinimized}>
        <ListGroup>
          {cart.map(item => (
            <ListGroupItem key={item.id}>
              {item.name} - ₹{parseFloat(item.price).toFixed(2)} x {item.quantity}
              <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginTop: '10px' }}>
                <Button color="danger" onClick={() => updateQuantity(item.id, item.quantity - 1)}> - </Button>
                <span style={{ margin: '0 10px', fontWeight: 'bold' }}>{item.quantity}</span>
                <Button color="success" onClick={() => updateQuantity(item.id, item.quantity + 1)}> + </Button>
              </div>
            </ListGroupItem>
          ))}
        </ListGroup>
        <p><strong>Total:</strong> $ {calculateTotalPrice()}</p>
        <PrimaryButton color="success" block onClick={proceedToCartReview}>
          Proceed to Cart Review
        </PrimaryButton>
      </MiniCartContent>
    </MiniCartContainer>
  );
};

const ProductSelection = ({ products, cart, addToCart, updateQuantity, proceedToCartReview, showProductDetails }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredProducts, setFilteredProducts] = useState(products);

  const handleSearch = () => {
    const filtered = products.filter(product =>
      product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      product.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
      product.barcode.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredProducts(filtered);
  };

  useEffect(() => {
    setFilteredProducts(products);
  }, [products]);

  return (
    <div>
      <h2>Select Products</h2>
      <div style={{ display: 'flex', alignItems: 'center', marginBottom: '20px' }}>
        <Input
          type="text"
          placeholder="Search by product name, description, or barcode"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ marginRight: '10px', borderRadius: '5px' }}
        />
        <Button color="primary" onClick={handleSearch}>
          Search
        </Button>
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px', padding: '20px' }}>
        {filteredProducts.map(product => {
          const cartItem = cart.find(item => item.id === product.id) || { quantity: 0 };
          return (
            <Card key={product.id} style={{ border: 'none', borderRadius: '15px', boxShadow: '0 10px 30px rgba(0, 0, 0, 0.1)', overflow: 'hidden', transition: 'transform 0.3s ease, box-shadow 0.3s ease' }}>
              <div
                style={{ backgroundImage: `url(${product.frontImage})`, backgroundSize: 'cover', height: '200px', cursor: 'pointer' }}
                onClick={() => showProductDetails(product)}
              >
                <div style={{ backgroundColor: 'rgba(0, 0, 0, 0.7)', color: 'white', padding: '10px', textAlign: 'center' }}>
                  <CardTitle tag="h5">{product.name}</CardTitle>
                  <CardText>₹{parseFloat(product.price || 0).toFixed(2)}</CardText>
                </div>
              </div>
              <CardBody className="text-center">
                <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginTop: '10px' }}>
                  <Button color="danger" onClick={() => updateQuantity(product.id, cartItem.quantity - 1)}> - </Button>
                  <span style={{ margin: '0 10px', fontWeight: 'bold' }}>{cartItem.quantity}</span>
                  <Button color="success" onClick={() => addToCart(product)}> + </Button>
                </div>
              </CardBody>
            </Card>
          );
        })}
      </div>
      <Button color="primary" onClick={proceedToCartReview} className="mt-3" disabled={cart.length === 0}>
        Proceed to Cart Review
      </Button>
    </div>
  );
};

const CartReview = ({ cart, updateQuantity, proceedToDetails }) => {
  return (
    <SectionContainer>
      <h2>Review Your Cart</h2>
      <ListGroup>
        {cart.map(item => (
          <ListGroupItem key={item.id}>
            {item.name} - ₹{parseFloat(item.price).toFixed(2)} x {item.quantity}
            <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginTop: '10px' }}>
              <Button color="danger" onClick={() => updateQuantity(item.id, item.quantity - 1)}> - </Button>
              <span style={{ margin: '0 10px', fontWeight: 'bold' }}>{item.quantity}</span>
              <Button color="success" onClick={() => updateQuantity(item.id, item.quantity + 1)}> + </Button>
            </div>
          </ListGroupItem>
        ))}
      </ListGroup>
      <PrimaryButton onClick={proceedToDetails} disabled={cart.length === 0} className="mt-3">
        Proceed to Enter Details
      </PrimaryButton>
    </SectionContainer>
  );
};

const PersonalDetails = ({ formData, setFormData, proceedToReview }) => {
  const [addressSuggestions, setAddressSuggestions] = useState([]);
  const [isValidating, setIsValidating] = useState(false);

  const validateEmail = (email) => {
    const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return regex.test(email);
  };

  const validatePhoneNumber = (phone) => {
    const regex = /^(\+61|0)[2-478]\d{8}$/;
    return regex.test(phone);
  };

  const handleInputChange = (e) => {
    const { id, value } = e.target;
    setFormData((prevFormData) => ({
      ...prevFormData,
      [id]: value,
    }));

    if (id === 'street' && value.length > 2) {
      validateStreet(value);
    }
  };

  const validateStreet = async (street) => {
    setIsValidating(true);
    try {
      const response = await axios.get('https://nominatim.openstreetmap.org/search', {
        params: {
          q: street,
          format: 'json',
          addressdetails: 1,
          countrycodes: 'au',
          limit: 5,
        },
      });
      const suggestions = response.data.map((result) => ({
        display_name: result.display_name,
        lat: result.lat,
        lon: result.lon,
        city: result.address.city || result.address.town || result.address.village,
        postalCode: result.address.postcode,
      }));
      setAddressSuggestions(suggestions);
    } catch (error) {
      console.error('Error validating street address:', error);
    } finally {
      setIsValidating(false);
    }
  };

  const handleAddressSelect = (suggestion) => {
    setFormData((prevFormData) => ({
      ...prevFormData,
      street: suggestion.display_name,
      city: suggestion.city,
      postalCode: suggestion.postalCode,
      latitude: suggestion.lat,
      longitude: suggestion.lon,
    }));
    setAddressSuggestions([]);
  };

  const isFormValid = () => {
    return (
      formData.name &&
      validateEmail(formData.email) &&
      validatePhoneNumber(formData.phone) &&
      formData.street &&
      formData.city &&
      formData.postalCode
    );
  };

  return (
    <SectionContainer>
      <h2>Enter Your Details</h2>
      <Form>
        <FormGroup>
          <Label for="name">Name</Label>
          <Input
            type="text"
            id="name"
            value={formData.name}
            onChange={handleInputChange}
            placeholder="Enter your full name"
          />
        </FormGroup>
        <FormGroup>
          <Label for="phone">Phone Number</Label>
          <Input
            type="text"
            id="phone"
            value={formData.phone}
            onChange={handleInputChange}
            placeholder="Enter your phone number"
            invalid={formData.phone && !validatePhoneNumber(formData.phone)}
          />
        </FormGroup>
        <FormGroup>
          <Label for="email">Email</Label>
          <Input
            type="email"
            id="email"
            value={formData.email}
            onChange={handleInputChange}
            placeholder="Enter your email"
            invalid={formData.email && !validateEmail(formData.email)}
          />
        </FormGroup>

        {/* Address Section */}
        <AddressSection>
          <AddressLabel for="unitNumber">Unit Number</AddressLabel>
          <Input
            type="text"
            id="unitNumber"
            value={formData.unitNumber}
            onChange={handleInputChange}
            placeholder="Enter your unit number (optional)"
          />
          <AddressLabel for="street">Street Address</AddressLabel>
          <Input
            type="text"
            id="street"
            value={formData.street}
            onChange={handleInputChange}
            placeholder="Enter your street address"
          />
          {isValidating && <p>Validating street address...</p>}
          {addressSuggestions.length > 0 && (
            <ul style={{ listStyleType: 'none', paddingLeft: 0 }}>
              {addressSuggestions.map((suggestion, index) => (
                <ListGroupItem
                  key={index}
                  onClick={() => handleAddressSelect(suggestion)}
                  style={{ cursor: 'pointer' }}
                >
                  {suggestion.display_name}
                </ListGroupItem>
              ))}
            </ul>
          )}
          <AddressLabel for="city">City</AddressLabel>
          <Input
            type="text"
            id="city"
            value={formData.city}
            onChange={handleInputChange}
            placeholder="Enter your city"
          />
          <AddressLabel for="postalCode">Postal Code</AddressLabel>
          <Input
            type="text"
            id="postalCode"
            value={formData.postalCode}
            onChange={handleInputChange}
            placeholder="Enter your postal code"
          />
        </AddressSection>

        <FormGroup>
          <Label for="note">Note</Label>
          <Input
            type="textarea"
            id="note"
            value={formData.note}
            onChange={handleInputChange}
            placeholder="Add any special instructions or notes here"
          />
        </FormGroup>
        <PrimaryButton onClick={proceedToReview} disabled={!isFormValid()}>
          Proceed to Review
        </PrimaryButton>
      </Form>
    </SectionContainer>
  );
};

const ReviewOrder = ({ formData, cart, placeOrder }) => {
  const [isConfirmModalOpen, setConfirmModalOpen] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  const handleOrder = async () => {
    setIsProcessing(true);

    await placeOrder({ ...formData, cart, transactionType: 'online sale' });

    setIsProcessing(false);
    setConfirmModalOpen(false);
    alert('Order placed successfully!');
  };

  const calculateTotal = () => {
    return cart.reduce((sum, item) => sum + parseFloat(item.price) * item.quantity, 0).toFixed(2);
  };

  return (
    <SectionContainer>
      <h2>Review Your Order</h2>
      <h4>Personal Details</h4>
      <p><strong>Name:</strong> {formData.name}</p>
      <p><strong>Phone:</strong> {formData.phone}</p>
      <p><strong>Email:</strong> {formData.email}</p>
      <p><strong>Address:</strong> {`${formData.unitNumber ? formData.unitNumber + ', ' : ''}${formData.street}, ${formData.city}, ${formData.postalCode}`}</p>
      {formData.note && <p><strong>Note:</strong> {formData.note}</p>}
      <h4>Cart Items</h4>
      <ListGroup>
        {cart.map(item => (
          <ListGroupItem key={item.id}>
            {item.name} - ₹{parseFloat(item.price).toFixed(2)} x {item.quantity}
          </ListGroupItem>
        ))}
      </ListGroup>
      <h4>Total: ₹{calculateTotal()}</h4>
      <PrimaryButton color="success" onClick={() => setConfirmModalOpen(true)} className="mt-3">
        Confirm and Place Order
      </PrimaryButton>

      <Modal isOpen={isConfirmModalOpen} toggle={() => setConfirmModalOpen(!isConfirmModalOpen)}>
        <ModalHeader toggle={() => setConfirmModalOpen(!isConfirmModalOpen)}>Confirm Order</ModalHeader>
        <ModalBody>
          {isProcessing ? (
            <p>Processing your order, please wait...</p>
          ) : (
            <p>Are you sure you want to place this order?</p>
          )}
        </ModalBody>
        <ModalFooter>
          {!isProcessing && (
            <>
              <Button color="primary" onClick={handleOrder}>Yes, Place Order</Button>{' '}
              <Button color="secondary" onClick={() => setConfirmModalOpen(false)}>Cancel</Button>
            </>
          )}
        </ModalFooter>
      </Modal>
    </SectionContainer>
  );
};

const Stepper = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  width: 100%;
  background-color: #f4f4f9;
  padding: 10px;
  border-radius: 10px;
`;

const Step = styled.div`
  flex: 1;
  height: 8px;
  margin: 0 5px;
  background-color: ${({ isActive }) => (isActive ? theme.primary : '#ccc')};
  border-radius: 5px;
  transition: background-color 0.3s ease;
`;

const CustomerPOS = ({ userId }) => {
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    email: '',
    unitNumber: '',
    street: '',
    city: '',
    postalCode: '',
    latitude: '',
    longitude: '',
    note: '',
  });
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [isProductDetailsModalOpen, setProductDetailsModalOpen] = useState(false);

  useEffect(() => {
    const fetchProducts = async () => {
      const existingProducts = await loadProducts(userId);
      setProducts(existingProducts);
    };

    const fetchCart = async () => {
      const existingCart = await loadCart();
      setCart(existingCart);
    };

    fetchProducts();
    fetchCart();
  }, [userId]);

  const addToCart = (product) => {
    const existingProduct = cart.find(item => item.id === product.id);
    let updatedCart;

    if (existingProduct) {
      if (existingProduct.quantity + 1 > product.stock) {
        alert(`Not enough stock for ${product.name}. Only ${product.stock} available.`);
        return;
      }
      updatedCart = cart.map(item =>
        item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
      );
    } else {
      if (product.stock < 1) {
        alert(`Not enough stock for ${product.name}.`);
        return;
      }
      updatedCart = [...cart, { ...product, quantity: 1 }];
    }

    setCart(updatedCart);
    saveCart(updatedCart);
  };

  const updateQuantity = (productId, quantity) => {
    const product = products.find(prod => prod.id === productId);
    if (quantity > product.stock) {
      alert(`Not enough stock for ${product.name}. Only ${product.stock} available.`);
      return;
    }

    let updatedCart;
    if (quantity === 0) {
      updatedCart = cart.filter(item => item.id !== productId);
    } else {
      updatedCart = cart.map(item =>
        item.id === productId ? { ...item, quantity } : item
      );
    }

    setCart(updatedCart);
    saveCart(updatedCart);
  };

  const placeOrder = async (orderDetails) => {
    const invoiceNumber = `INV-${Date.now()}`;
    const total = cart.reduce((sum, item) => sum + parseFloat(item.price) * item.quantity, 0);
    const date = new Date().toISOString();
    const type = 'online sale';

    const order = {
      invoiceNumber,
      customerName: orderDetails.name,
      customerPhone: orderDetails.phone,
      customerEmail: orderDetails.email,
      total,
      status: 'Pending',
      date,
      type,
      cart: cart.map(item => ({
        id: item.id,
        name: item.name,
        price: parseFloat(item.price),
        quantity: item.quantity
      })),
      notes: orderDetails.note,
      deliveryLocation: {
        latitude: orderDetails.latitude,
        longitude: orderDetails.longitude,
      },
      address: `${orderDetails.unitNumber ? orderDetails.unitNumber + ', ' : ''}${orderDetails.street}, ${orderDetails.city}, ${orderDetails.postalCode}`
    };

    await createOrder(userId, order);

    setCart([]);
    saveCart([]);
    setStep(1);

    alert('Order placed successfully!');
  };

  const showProductDetails = (product) => {
    setSelectedProduct(product);
    setProductDetailsModalOpen(true);
  };

  const renderStep = () => {
    switch (step) {
      case 1:
        return (
          <ProductSelection
            products={products}
            cart={cart}
            addToCart={addToCart}
            updateQuantity={updateQuantity}
            proceedToCartReview={() => setStep(2)}
            showProductDetails={showProductDetails}
          />
        );
      case 2:
        return (
          <CartReview
            cart={cart}
            updateQuantity={updateQuantity}
            proceedToDetails={() => setStep(3)}
          />
        );
      case 3:
        return (
          <PersonalDetails
            formData={formData}
            setFormData={setFormData}
            proceedToReview={() => setStep(4)}
          />
        );
      case 4:
        return (
          <ReviewOrder
            formData={formData}
            cart={cart}
            placeOrder={placeOrder}
          />
        );
      default:
        return null;
    }
  };

  return (
    <>
      <StyledContainer>
        <Stepper>
          <Step isActive={step >= 1} onClick={() => setStep(1)} />
          <Step isActive={step >= 2} onClick={() => setStep(2)} />
          <Step isActive={step >= 3} onClick={() => setStep(3)} />
          <Step isActive={step >= 4} onClick={() => setStep(4)} />
        </Stepper>
        {renderStep()}
        <ProductDetailsModal
          product={selectedProduct}
          isOpen={isProductDetailsModalOpen}
          toggle={() => setProductDetailsModalOpen(!isProductDetailsModalOpen)}
        />
      </StyledContainer>
      {step === 1 && <MiniCart cart={cart} updateQuantity={updateQuantity} proceedToCartReview={() => setStep(2)} />}
      <CustomerFooter />
    </>
  );
};

export default CustomerPOS;
