// General function to get data by key
export const getData = (key) => {
  console.log('Getting data for key:', key); // Debug statement
  const data = STORAGE.getItem(key);
  return data ? JSON.parse(data) : [];
};

// General function to set data by key
export const setData = (key, data) => {
  console.log('Setting data for key:', key, 'with data:', data); // Debug statement
  STORAGE.setItem(key, JSON.stringify(data));
};

// Helper function to generate a unique ID
export const generateUniqueId = () => {
  return '_' + Math.random().toString(36).substr(2, 9);
};

// Add data to a specific key with a unique ID
export const addData = (key, item) => {
  const data = getData(key);
  const newItem = item;
  data.push(newItem);
  setData(key, data);
  console.log('Added data with unique ID:', newItem); // Debug statement
};

// Update data by key and id
export const updateData = (key, updatedItem, idField = 'id') => {
  console.log('Updating data for key:', key, 'with updated item:', updatedItem); // Debug statement
  let data = getData(key);
  data = data.map(item => (item[idField] === updatedItem[idField] ? updatedItem : item));
  setData(key, data);
};

// Delete data by key and id
export const deleteData = (key, id, idField = 'id') => {
  console.log('Deleting data for key:', key, 'with id:', id); // Debug statement
  let data = getData(key);
  data = data.filter(item => item[idField] !== id);
  setData(key, data);
};

// Clear specific data by key
export const clearData = (key) => {
  console.log('Clearing data for key:', key); // Debug statement
  STORAGE.removeItem(key);
};

// Clear all local storage
export const clearLocalStorage = () => {
  console.log('Clearing all local storage'); // Debug statement
  STORAGE.clear();
};

