// Helper function to fetch data from the server and store it in local storage
const fetchAndStorePaginatedProducts = async (page = 1, pageSize = 200) => {
  const token = getAuthToken();
  const userId = getUserId();
  let allProducts = [];
  let hasMore = true;

  try {
    console.log('Starting paginated fetch operation for products from server...');
    console.log(`Token: ${token}, User ID: ${userId}`); // Debug statement

    while (hasMore) {
      console.log(`Fetching page ${page} with page size ${pageSize}...`); // Debug statement
      const response = await fetch(`${BASE_URL}/products/paginated?page=${page}&pageSize=${pageSize}`, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
          'user_id': userId,
        },
      });

      if (response.status === 200) {
        const data = await handleResponse(response);

        const { products, total_count, total_pages } = data;

        console.log(`Page ${page} fetched successfully:`, products); // Debug statement

        // Append products to the master array
        allProducts = [...allProducts, ...products];

        // Check if more pages are available
        if (page >= total_pages || allProducts.length >= total_count) {
          hasMore = false;
        } else {
          page++; // Increment to the next page
        }
      } else {
        console.warn('Fetching failed. Clearing local storage.'); // Debug statement
        clearData('products');
        return false; // Indicate failure
      }
    }

    console.log('All products fetched from server:', allProducts); // Debug statement

    // Clear existing products in local storage before adding the new ones
    clearData('products');
    allProducts.forEach(product => addData('products', product)); // Add each fetched product individually to local storage

    cachedProducts = Array.isArray(allProducts) ? allProducts : null; // Update cache
    productsFetchTime = Date.now();
    console.log('All products added individually to local storage'); // Debug statement
    return true; // Indicate success
  } catch (error) {
    alert('Error occurred during paginated product fetch operation:', error); // Debug statement
    clearData('products'); // Clear products in case of an error
    return false; // Indicate failure
  }
};


