// Fetch all suppliers with pagination and caching
const fetchAndStorePaginatedSuppliers = async (page = 1, pageSize = 200) => {
  const token = getAuthToken();
  const userId = getUserId();
  let allSuppliers = [];
  let hasMore = true;

  try {
    while (hasMore) {
      const response = await fetch(
        `${BASE_URL}/suppliers/paginated?page=${page}&pageSize=${pageSize}`,
        {
          method: 'GET',
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
            user_id: userId,
          },
        }
      );

      if (response.status === 200) {
        const { suppliers, total_count, total_pages } = await handleResponse(response);
        allSuppliers = [...allSuppliers, ...suppliers];
        if (page >= total_pages || allSuppliers.length >= total_count) {
          hasMore = false;
        } else {
          page++;
        }
      } else {
        clearData('suppliers');
        return false;
      }
    }

    clearData('suppliers');
    allSuppliers.forEach((supplier) => addData('suppliers', supplier));
    cachedSuppliers = Array.isArray(allSuppliers) ? allSuppliers : null;
    suppliersFetchTime = Date.now();
    return true;
  } catch (error) {
    clearData('suppliers');
    console.error('Error fetching suppliers:', error);
    return false;
  }
};

