// Helper function to fetch paginated transactions
const fetchPaginatedTransactions = async (filters = {}, page = 1, pageSize = 100) => {
  const token = getAuthToken();
  const userId = getUserId();
  let allTransactions = [];
  let hasMorePages = true;

  try {
    console.log('Starting paginated fetch operation for transactions...');
    console.log(`Filters: ${JSON.stringify(filters)}, Page: ${page}, Page Size: ${pageSize}`); // Debug statement

    while (hasMorePages) {
      console.log(`Fetching page ${page}...`); // Debug statement
      const response = await fetch(`${BASE_URL}/transactionsV2?page=${page}&pageSize=${pageSize}`, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
          'user_id': userId,
        },
      });

      if (response.status === 200) {
        const data = await handleResponse(response);
        const { transactions, totalPages } = data;

        console.log(`Page ${page} fetched successfully:`, transactions); // Debug statement

        // Append transactions to the master array
        allTransactions = [...allTransactions, ...transactions];

        // Determine if more pages are available
        if (page >= totalPages) {
          hasMorePages = false;
        } else {
          page++; // Increment to the next page
        }
      } else {
        console.warn('Failed to fetch transactions.'); // Debug statement
        return null; // Return null to indicate failure
      }
    }

    clearData('transactions');
    // Add each fetched transaction individually to local storage
    allTransactions.forEach(transaction => addData('transactions', transaction));
    console.log('All transactions added individually to local storage'); // Debug statement

    console.log('All transactions fetched:', allTransactions); // Debug statement
    cachedTransactions = Array.isArray(allTransactions) ? allTransactions : null; //added to the cash
    transactionsFetchTime = Date.now();

    return allTransactions; // Return all fetched transactions
  } catch (error) {
    console.error('Error fetching paginated transactions:', error); // Debug statement
    return null; // Return null to indicate failure
  }
};





