import React, { useState, useEffect } from 'react';
import {
  Container,
  Row,
  Col,
  Card,
  CardBody,
  CardHeader,
  Button,
  FormGroup,
  Label,
  Input,
  Modal,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Spinner,
} from 'reactstrap';
import styled from 'styled-components';
import {
  FaStore,
  FaClock,
  FaMoneyBillWave,
  FaUserLock,
  FaSave,
  FaEdit,
  FaCreditCard,
  FaFacebook,
  FaTwitter,
  FaInstagram,
  FaBell,
  FaFileInvoice,
  FaUniversity,
  FaImage,
} from 'react-icons/fa';
import { loadProfile, saveProfile, changePassword } from '../auth/api';
import currencyFormatter from 'currency-formatter';

import { Tabs } from 'antd';
const { TabPane } = Tabs;

const StyledContainer = styled.div`
  padding: 2rem;
  padding-top: 0rem;
  background-color: #f5f5f5;
  min-height: calc(100vh - 40px - 100px);
  max-height: calc(100vh - 40px - 20px);
  
`;

const GradientCard = styled(Card)`
  margin-bottom: 10px;
  transition: transform 0.2s, box-shadow 0.2s;
  
  
`;
/*


const GradientCard = styled(Card)`
  margin-bottom: 20px;
  border-radius: 10px;
  background: linear-gradient(135deg, #003459, #007ea7);
  color: white;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);

  &:hover {
    transform: scale(1.05);
    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2);
  }
`;
*/
const ProfilePage = () => {
  const [profileData, setProfileData] = useState({
    businessName: '',
    address: '',
    email: '',
    phoneNumber: '', 
    businessIdName: '',
    businessIdNumber: '',
    gstRegistered: true,
    bankingDetails: {
      selectedCountry: '',
      details: {}, // Initialize details as an empty object
    },
    businessHours: '',
    paymentMethods: [],
    socialMedia: {
      facebook: '',
      twitter: '',
      instagram: '',
    },
    taxName: '',
    taxPercentage: 0,
    invoiceDisclaimer: '',
    notificationSettings: {
      email: false,
      sms: false,
    },
    logoBase64: '',
    currency: 'USD', // Add default currency here
  });
  const [isEditing, setIsEditing] = useState(false);
  const [percentage, setPercentage] = useState(0);
  const [passwordModal, setPasswordModal] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmNewPassword, setConfirmNewPassword] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  const [selectedCountry, setSelectedCountry] = useState(''); // Default to an empty string or a default country.
  const [currency, setCurrency] = useState('USD');
  useEffect(() => {
    const fetchProfile = async () => {
      const profile = await loadProfile();
      setCurrency(profile.currency || 'USD'); // Default to USD if no currency is set
    };
    fetchProfile();
  }, []);

  // Load profile data when the component mounts
  useEffect(() => {
    const fetchProfile = async () => {
      const savedProfile = await loadProfile();
      setProfileData((prevData) => ({
        ...prevData,
        ...savedProfile,
      }));
      setPercentage(savedProfile.taxPercentage || 0);
    };

    fetchProfile();
  }, []);

  const handleSaveProfile = async () => {
    setIsProcessing(true);
    try {
      await saveProfile({
        ...profileData,
        taxPercentage: percentage,
        bankingDetails: {
          selectedCountry: profileData.bankingDetails.selectedCountry,
          details: profileData.bankingDetails.details,
        },
      });
      alert('Profile saved successfully!');
      setIsEditing(false);
    } catch (error) {
      alert('Failed to save profile. Please try again.');
    } finally {
      setIsProcessing(false);
    }
  };

  const handleBankingDetailsChange = (field, value) => {
    setProfileData((prevData) => ({
      ...prevData,
      bankingDetails: {
        ...prevData.bankingDetails,
        details: {
          ...prevData.bankingDetails.details,
          [field]: value,
        },
      },
    }));
  };

  const handleCountryChange = (value) => {
    setProfileData((prevData) => ({
      ...prevData,
      bankingDetails: {
        ...prevData.bankingDetails,
        selectedCountry: value,
      },
    }));
  };
  
  const handleEditToggle = () => {
    setIsEditing((prev) => !prev);
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setProfileData((prevData) => ({
      ...prevData,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  const handlePercentageChange = (e) => {
    setPercentage(e.target.value);
  };

  const handleLogoUpload = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();
    reader.onloadend = () => {
      setProfileData((prevData) => ({
        ...prevData,
        logoBase64: reader.result,
      }));
    };
    if (file) {
      reader.readAsDataURL(file);
    }
  };

  const togglePasswordModal = () => setPasswordModal(!passwordModal);

  const handlePasswordChange = () => {
    if (newPassword === confirmNewPassword) {
      changePassword(newPassword);
      //alert('Password changed successfully!');
      togglePasswordModal();
    } else {
      alert('Passwords do not match!');
    }
  };

  const handleSocialMediaChange = (platform, value) => {
    setProfileData((prevData) => ({
      ...prevData,
      socialMedia: {
        ...prevData.socialMedia,
        [platform]: value,
      },
    }));
  };

  const bankingFieldsByCountry = {
    Australia: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'bsbNumber', label: 'BSB Number', type: 'text', required: true },
    ],
    UnitedStates: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'routingNumber', label: 'Routing Number', type: 'text', required: true },
    ],
    Europe: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'iban', label: 'IBAN', type: 'text', required: true },
      { field: 'swiftCode', label: 'SWIFT/BIC Code', type: 'text', required: true },
    ],
    UnitedKingdom: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'sortCode', label: 'Sort Code', type: 'text', required: true },
    ],
    Canada: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'institutionNumber', label: 'Institution Number', type: 'text', required: true },
      { field: 'transitNumber', label: 'Transit Number', type: 'text', required: true },
    ],
    India: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'ifscCode', label: 'IFSC Code', type: 'text', required: true },
    ],
    Japan: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'bankCode', label: 'Bank Code', type: 'text', required: true },
      { field: 'branchCode', label: 'Branch Code', type: 'text', required: true },
    ],
    China: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'cnapsCode', label: 'CNAPS Code', type: 'text', required: true },
    ],
    Brazil: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'bankCode', label: 'Bank Code', type: 'text', required: true },
      { field: 'branchCode', label: 'Branch Code', type: 'text', required: true },
    ],
    SouthAfrica: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'branchCode', label: 'Branch Code', type: 'text', required: true },
    ],
    NewZealand: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'bankCode', label: 'Bank Code', type: 'text', required: true },
      { field: 'branchCode', label: 'Branch Code', type: 'text', required: true },
    ],
    Mexico: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'clabe', label: 'CLABE', type: 'text', required: true },
    ],
    Russia: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'bik', label: 'BIK', type: 'text', required: true },
    ],
    Singapore: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'bankCode', label: 'Bank Code', type: 'text', required: true },
      { field: 'branchCode', label: 'Branch Code', type: 'text', required: true },
    ],
    HongKong: [
      { field: 'accountHolderName', label: 'Account Holder Name', type: 'text', required: true },
      { field: 'accountNumber', label: 'Account Number', type: 'text', required: true },
      { field: 'bankCode', label: 'Bank Code', type: 'text', required: true },
      { field: 'branchCode', label: 'Branch Code', type: 'text', required: true },
    ],
    // Add more countries here following the same structure
  };
  const taxNamesByCountry = {
    Australia: ['GST'],
    UnitedStates: ['Sales Tax'],
    Europe: ['VAT'],
    UnitedKingdom: ['VAT'],
    Canada: ['GST', 'HST'],
    India: ['GST'],
    Japan: ['Consumption Tax'],
    China: ['VAT'],
    Brazil: ['ICMS'],
    SouthAfrica: ['VAT'],
    NewZealand: ['GST'],
    Mexico: ['IVA'],
    Russia: ['VAT'],
    Singapore: ['GST'],
    HongKong: ['Business Tax'],
    // Add more countries and tax names as needed
  };
  
  
  return (
    <StyledContainer>
      <Tabs defaultActiveKey="1" >
        {/* Business Details */}
        <TabPane tab="Business Details" key="1">
      <Row>
        <Col md={12}>
          <GradientCard>
            <CardHeader>
              <FaStore /> Business Details
            </CardHeader>
            <CardBody>
              {isEditing ? (
                <>
                  <FormGroup>
                    <Label for="businessName">Business Name</Label>
                    <Input
                      type="text"
                      name="businessName"
                      id="businessName"
                      value={profileData.businessName || ''}
                      onChange={handleInputChange}
                    />
                  </FormGroup>
                  <FormGroup>
                    <Label for="address">Address</Label>
                    <Input
                      type="text"
                      name="address"
                      id="address"
                      value={profileData.address || ''}
                      onChange={handleInputChange}
                    />
                  </FormGroup>
                  <FormGroup>
                    <Label for="email">Email</Label>
                    <Input
                      type="email"
                      name="email"
                      id="email"
                      value={profileData.email || ''}
                      onChange={handleInputChange}
                    />
                  </FormGroup>
                  <FormGroup>
                    <Label for="phoneNumber">Phone Number</Label>
                    <Input
                      type="text"
                      name="phoneNumber"
                      id="phoneNumber"
                      value={profileData.phoneNumber || ''}
                      onChange={handleInputChange}
                    />
                  </FormGroup>
                  <FormGroup>
                    <Label for="busineddIdName">Business Id Name (eg. ABN, GST etc..)</Label>
                    <Input
                      type="text"
                      name="businessIdName"
                      id="businessIdName"
                      value={profileData.businessIdName || ''}
                      onChange={handleInputChange}
                    />
                  </FormGroup>
                  <FormGroup>
                    <Label for="businessIdNumber">{profileData.businessIdName} Number</Label>
                    <Input
                      type="text"
                      name="businessIdNumber"
                      id="businessIdNumber"
                      value={profileData.businessIdNumber || ''}
                      onChange={handleInputChange}
                    />
                  </FormGroup>
                  <FormGroup>
                    <Label for="currency">Currency</Label>
                    <Input
                      type="select"
                      name="currency"
                      id="currency"
                      value={profileData.currency}
                      onChange={handleInputChange}
                    >
                      <option value="USD">USD - US Dollar</option>
                      <option value="EUR">EUR - Euro</option>
                      <option value="GBP">GBP - British Pound</option>
                      <option value="AUD">AUD - Australian Dollar</option>
                      <option value="INR">INR - Indian Rupee</option>
                      <option value="JPY">JPY - Japanese Yen</option>
                      <option value="CAD">CAD - Canadian Dollar</option>
                      <option value="CHF">CHF - Swiss Franc</option>
                      <option value="CNY">CNY - Chinese Yuan</option>
                      <option value="BRL">BRL - Brazilian Real</option>
                      <option value="RUB">RUB - Russian Ruble</option>
                      <option value="ZAR">ZAR - South African Rand</option>
                      <option value="KRW">KRW - South Korean Won</option>
                      <option value="MXN">MXN - Mexican Peso</option>
                      <option value="TRY">TRY - Turkish Lira</option>
                      <option value="SGD">SGD - Singapore Dollar</option>
                      <option value="HKD">HKD - Hong Kong Dollar</option>
                      <option value="MYR">MYR - Malaysian Ringgit</option>
                      <option value="PHP">PHP - Philippine Peso</option>
                      <option value="THB">THB - Thai Baht</option>
                      <option value="IDR">IDR - Indonesian Rupiah</option>
                      <option value="VND">VND - Vietnamese Đồng</option>
                    </Input>
                  </FormGroup>

                  <FormGroup>
                    <Label for="taxName">Select Tax Name</Label>
                    <Input
                      type="select"
                      name="taxName"
                      id="taxName"
                      value={profileData.taxName || ''}
                      onChange={(e) => {
                        const selectedTaxName = e.target.value;
                        setProfileData((prevData) => ({
                          ...prevData,
                          taxName: selectedTaxName,
                        }));
                      }}
                    >
                      {(taxNamesByCountry[profileData.bankingDetails?.selectedCountry] || []).map((tax) => (
                        <option key={tax} value={tax}>
                          {tax}
                        </option>
                      ))}
                    </Input>
                  </FormGroup>

                  <FormGroup>
                    <Label for="percentage">Tax Percentage</Label>
                    <Input
                      type="number"
                      name="percentage"
                      id="percentage"
                      value={percentage}
                      onChange={handlePercentageChange}
                    />
                  </FormGroup>
                  <FormGroup>
                    <Label for="invoiceDisclaimer">Invoice Disclaimer</Label>
                    <Input
                      type="textarea"
                      name="invoiceDisclaimer"
                      id="invoiceDisclaimer"
                      value={profileData.invoiceDisclaimer || ''}
                      onChange={handleInputChange}
                    />
                  </FormGroup>
                </>
              ) : (
                <>
                  <p><strong>Business Name:</strong> {profileData.businessName || 'N/A'}</p>
                  <p><strong>Address:</strong> {profileData.address || 'N/A'}</p>
                  <p><strong>Email:</strong> {profileData.email || 'N/A'}</p>
                  <p><strong>Phone Number:</strong> {profileData.phoneNumber || 'N/A'}</p>
                  <p><strong>{profileData.businessIdName}:</strong> {profileData.businessIdNumber || 'N/A'}</p>
                  <p><strong>Currency:</strong> {profileData.currency || 'USD'}</p>
                  <p><strong>Tax Name:</strong> {profileData.taxName || 'N/A'}</p>
                  <p><strong>Tax Percentage:</strong> {percentage || 'N/A'}%</p>
                  <p><strong>Invoice Disclaimer:</strong> {profileData.invoiceDisclaimer || 'N/A'}</p>
                </>
              )}
            </CardBody>
          </GradientCard>
        </Col>
        </Row>
        </TabPane>

        <TabPane tab="Bank Details" key="2">
          <Row>
            <Col md={12}>
              <GradientCard>
                <CardHeader>
                  <FaUniversity /> Bank Details
                </CardHeader>
                <CardBody>
                  {isEditing ? (
                    <>
                      {/* Country Dropdown */}
                      <FormGroup>
                        <Label for="country">Select Country</Label>
                        <Input
                          type="select"
                          id="country"
                          value={profileData.bankingDetails?.selectedCountry || ''}
                          onChange={(e) => {
                            const newCountry = e.target.value;
                            setProfileData((prev) => ({
                              ...prev,
                              bankingDetails: {
                                selectedCountry: newCountry, // Update selected country
                                details: {}, // Reset details when country changes
                              },
                            }));
                          }}
                        >
                          {Object.keys(bankingFieldsByCountry).map((country) => (
                            <option key={country} value={country}>
                              {country}
                            </option>
                          ))}
                        </Input>
                      </FormGroup>

                      {/* Dynamic Fields */}
                      {bankingFieldsByCountry[profileData.bankingDetails.selectedCountry]?.map((field) => (
                        <FormGroup key={field.field}>
                          <Label for={field.field}>{field.label}</Label>
                          <Input
                            type={field.type}
                            id={field.field}
                            value={profileData.bankingDetails?.details?.[field.field] || ''}
                            onChange={(e) =>
                              setProfileData((prev) => ({
                                ...prev,
                                bankingDetails: {
                                  ...prev.bankingDetails,
                                  details: {
                                    ...(prev.bankingDetails?.details || {}),
                                    [field.field]: e.target.value,
                                  },
                                  taxName: taxNamesByCountry[selectedCountry]?.[0] || '',
                                },
                              }))
                            }
                          />
                        </FormGroup>
                      ))}
                    </>
                  ) : (
                    <>
                      <p>
                        <strong>Country:</strong> {profileData.bankingDetails.selectedCountry || 'N/A'}
                      </p>
                      {bankingFieldsByCountry[profileData.bankingDetails.selectedCountry]?.map((field) => (
                        <p key={field.field}>
                          <strong>{field.label}:</strong> {profileData.bankingDetails?.details?.[field.field] || 'N/A'}
                        </p>
                      ))}
                    </>
                  )}
                </CardBody>
              </GradientCard>
            </Col>
          </Row>
        </TabPane>



        {/* Social Media */}
        <TabPane tab="Social Media" key="3">
          <Row>
        <Col md={12}>
          <GradientCard>
            <CardHeader>
              <FaFacebook /> Social Media Links
            </CardHeader>
            <CardBody>
              {isEditing ? (
                <>
                  <FormGroup>
                    <Label for="facebook">Facebook</Label>
                    <Input
                      type="url"
                      name="facebook"
                      id="facebook"
                      value={profileData.socialMedia.facebook}
                      onChange={(e) => handleSocialMediaChange('facebook', e.target.value)}
                    />
                  </FormGroup>
                  <FormGroup>
                    <Label for="twitter">Twitter</Label>
                    <Input
                      type="url"
                      name="twitter"
                      id="twitter"
                      value={profileData.socialMedia.twitter}
                      onChange={(e) => handleSocialMediaChange('twitter', e.target.value)}
                    />
                  </FormGroup>
                  <FormGroup>
                    <Label for="instagram">Instagram</Label>
                    <Input
                      type="url"
                      name="instagram"
                      id="instagram"
                      value={profileData.socialMedia.instagram}
                      onChange={(e) => handleSocialMediaChange('instagram', e.target.value)}
                    />
                  </FormGroup>
                </>
              ) : (
                <>
                  <p><strong>Facebook:</strong> {profileData.socialMedia.facebook || 'N/A'}</p>
                  <p><strong>Twitter:</strong> {profileData.socialMedia.twitter || 'N/A'}</p>
                  <p><strong>Instagram:</strong> {profileData.socialMedia.instagram || 'N/A'}</p>
                </>
              )}
            </CardBody>
          </GradientCard>
        </Col>
        </Row>
        </TabPane>
        <TabPane tab="Notification Settings" key="5">
 
        {/* Notification Settings Section */}
           <Row>
        <Col md={12}>
          <GradientCard>
            <CardHeader>
              <FaBell /> Notification Settings
            </CardHeader>
            <CardBody>
              {isEditing ? (
                <>
                  <FormGroup check>
                    <Label check>
                      <Input
                        type="checkbox"
                        name="email"
                        checked={profileData.notificationSettings.email}
                        onChange={(e) =>
                          setProfileData((prevData) => ({
                            ...prevData,
                            notificationSettings: {
                              ...prevData.notificationSettings,
                              email: e.target.checked,
                            },
                          }))
                        }
                      />
                      Email Notifications
                    </Label>
                  </FormGroup>
                  <FormGroup check>
                    <Label check>
                      <Input
                        type="checkbox"
                        name="sms"
                        checked={profileData.notificationSettings.sms}
                        onChange={(e) =>
                          setProfileData((prevData) => ({
                            ...prevData,
                            notificationSettings: {
                              ...prevData.notificationSettings,
                              sms: e.target.checked,
                            },
                          }))
                        }
                      />
                      SMS Notifications
                    </Label>
                  </FormGroup>
                </>
              ) : (
                <>
                  <p><strong>Email Notifications:</strong> {profileData.notificationSettings.email ? 'Enabled' : 'Disabled'}</p>
                  <p><strong>SMS Notifications:</strong> {profileData.notificationSettings.sms ? 'Enabled' : 'Disabled'}</p>
                </>
              )}
            </CardBody>
          </GradientCard>
        </Col>
      </Row>
      </TabPane>
      <TabPane tab="Logo Section" key="6">

      {/* Logo Section */}
      <Row>
        <Col md={12}>
          <GradientCard>
            <CardHeader>
              <FaImage /> Logo
            </CardHeader>
            <CardBody>
              {isEditing ? (
                <FormGroup>
                  <Input type="file" accept="image/*" onChange={handleLogoUpload} />
                  {profileData.logoBase64 && (
                    <img src={profileData.logoBase64} alt="Business Logo" style={{ width: '100px', marginTop: '10px' }} />
                  )}
                </FormGroup>
              ) : (
                profileData.logoBase64 && (
                  <img src={profileData.logoBase64} alt="Business Logo" style={{ width: '100px', marginTop: '10px' }} />
                )
              )}
            </CardBody>
          </GradientCard>
        </Col>

        </Row>
      </TabPane>
      <TabPane tab="Change Password Section" key="7">

      {/* Change Password Section */}
      <Row>
        {/* Change Password Section */}
        <Col md={12}>
          <GradientCard>
            <CardHeader>
              <FaUserLock /> Change Password
            </CardHeader>
            <CardBody className="text-center">
              <Button color="secondary" onClick={togglePasswordModal}>
                Change Password
              </Button>
            </CardBody>
          </GradientCard>
        </Col>
      </Row>
      </TabPane>
      </Tabs>
      <Row>
        <Col className="text-center">
          {isEditing ? (
            <>
              <Button color="primary" onClick={handleSaveProfile}>
                <FaSave /> Save
              </Button>{' '}
              <Button color="secondary" onClick={handleEditToggle}>
                Cancel
              </Button>
            </>
          ) : (
            <Button color="primary" onClick={handleEditToggle}>
              <FaEdit /> Edit
            </Button>
          )}
        </Col>
      </Row>

      {/* Password Modal */}
      <Modal isOpen={passwordModal} toggle={togglePasswordModal}>
        <ModalHeader toggle={togglePasswordModal}>Change Password</ModalHeader>
        <ModalBody>
          <FormGroup>
            <Label for="newPassword">New Password</Label>
            <Input
              type="password"
              name="newPassword"
              id="newPassword"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
            />
          </FormGroup>
          <FormGroup>
            <Label for="confirmNewPassword">Confirm New Password</Label>
            <Input
              type="password"
              name="confirmNewPassword"
              id="confirmNewPassword"
              value={confirmNewPassword}
              onChange={(e) => setConfirmNewPassword(e.target.value)}
            />
          </FormGroup>
        </ModalBody>
        <ModalFooter>
          <Button color="primary" onClick={handlePasswordChange}>
            Save Password
          </Button>
          <Button color="secondary" onClick={togglePasswordModal}>
            Cancel
          </Button>
        </ModalFooter>
      </Modal>

      {/* Processing Modal */}
      <Modal isOpen={isProcessing}>
        <ModalBody className="text-center">
          <Spinner color="primary" />
          <p>Processing your request...</p>
        </ModalBody>
      </Modal>
    </StyledContainer>
  );
  
};

export default ProfilePage;
