import React, { useState, useEffect } from 'react';
// src/index.js or src/App.js
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap/dist/js/bootstrap.bundle.min.js';


//import { HashRouter as Router, Route, Routes, Navigate, useParams, useNavigate } from 'react-router-dom';
import { BrowserRouter as Router, Route, Routes, Navigate, useParams, useNavigate } from 'react-router-dom';
import Header from './components/admin/Header';
import Footer from './components/admin/Footer';
import Sidebar from './components/admin/Sidebar';
import ManageProducts from './components/admin/ManageProducts';
import InventoryManagement from './components/admin/InventoryManagement';
import POS from './components/admin/POS';
import SalesHistory from './components/admin/SalesHistory';
import SalesAnalytics from './components/admin/SalesAnalytics';
import Login from './components/auth/Login';
import CustomerPOS from './components/customerPOS/CustomerPOS';
import Checkout from './components/customerPOS/Checkout';
import OrderTracking from './components/customerPOS/OrderTracking';
import CustomerHeader from './components/customerPOS/CustomerHeader';
import CustomerFooter from './components/customerPOS/CustomerFooter';
import Home from './components/Home';
import Profile from './components/admin/Profile';
import Settings from './components/admin/Settings';
import OnlineOrderManagement from './components/admin/OnlineOrderManagement';
import ManageSuppliers from './components/admin/ManageSuppliers'
import styled from 'styled-components';
import { Button, Input } from 'antd';
import { login as apiLogin, clearLocalStorage } from './components/auth/api';

const MainContent = styled.div`
  padding-top: 80px;
  padding-bottom: 40px;
  margin-left: ${({ isSidebarOpen }) => (isSidebarOpen ? '220px' : '60px')};
  transition: margin-left 0.3s ease, width 0.3s ease;
  width: ${({ isSidebarOpen }) => (isSidebarOpen ? 'calc(100% - 220px)' : 'calc(100% - 60px)')};

  @media (max-width: 768px) {
    margin-left: 0;
    width: 100%;
  }
`;

function UsernamePrompt() {
  const [username, setUsername] = useState('');
  const navigate = useNavigate();

  const handleSubmit = () => {
    if (username.trim()) {
      navigate(`/${username}`);
    } else {
      alert('Please enter a valid username');
    }
  };

  return (
    <div style={{ textAlign: 'center', padding: '2rem' }}>
      <h1>Enter Your Username</h1>
      <Input
        placeholder="Username"
        value={username}
        onChange={(e) => setUsername(e.target.value)}
        style={{ width: '300px', marginBottom: '1rem' }}
      />
      <br />
      <Button type="primary" onClick={handleSubmit}>
        Submit
      </Button>
    </div>
  );
}

const BASE_URL = process.env.REACT_APP_BASE_URL;

function AppContent({ username }) {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [userId, setUserId] = useState(null);

  useEffect(() => {
    if (username) {
      fetch(`${BASE_URL}/auth/getUserId/${username}`)
        .then((response) => response.json())
        .then((data) => setUserId(data.user_id))
        .catch((error) => console.error('Error fetching user ID:', error));
    }
  }, [username]);

  const handleLogin = async (username, password) => {
    try {
      const response = await apiLogin({ username, password });
      setIsAuthenticated(true);
      clearLocalStorage();
      localStorage.setItem('authToken', response.token);
      localStorage.setItem('userId', response.user_id);
    } catch (error) {
      alert('Invalid credentials or login failed');
      console.error('Login error:', error.message);
    }
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    localStorage.removeItem('authToken');
    localStorage.removeItem('userId');
  };

  const toggleSidebar = (state) => {
    setIsSidebarOpen(state);
  };

  return (
    <>
      {isAuthenticated ? <Header /> : <CustomerHeader />}
      {isAuthenticated && (
        <Sidebar
          handleLogout={handleLogout}
          toggleSidebar={toggleSidebar}
          isOpen={isSidebarOpen}
          username={username}
          userId={userId}
        />
      )}
      <MainContent isSidebarOpen={isSidebarOpen}>
        <Routes>
          <Route path="/" element={<Home username={username} userId={userId} />} />
          <Route path="/customer-pos" element={<CustomerPOS username={username} userId={userId} />} />
          <Route path="/checkout" element={<Checkout username={username} userId={userId} />} />
          <Route path="/order-tracking" element={<OrderTracking username={username} userId={userId} />} />
          <Route
            path="/admin"
            element={!isAuthenticated ? <Login handleLogin={handleLogin} /> : <Navigate to={`/${username}/pos`} />}
          />
          {isAuthenticated ? (
            <>
              <Route path="/manage-products" element={<ManageProducts username={username} userId={userId} />} />
              <Route path="/inventory-management" element={<InventoryManagement username={username} userId={userId} />} />
              <Route path="/suppliers" element={<ManageSuppliers />} />
              <Route path="/pos" element={<POS username={username} userId={userId} />} />
              <Route path="/sales-history" element={<SalesHistory username={username} userId={userId} />} />
              <Route path="/sales-analytics" element={<SalesAnalytics username={username} userId={userId} />} />
              <Route path="/profile" element={<Profile username={username} userId={userId} />} />
              <Route path="/settings" element={<Settings username={username} userId={userId} />} />
              <Route path="/online-order-management" element={<OnlineOrderManagement username={username} userId={userId} />} />
              <Route path="*" element={<Navigate to="/pos" />} />
            </>
          ) : (
            <Route path="*" element={<Navigate to="/" />} />
          )}
        </Routes>
      </MainContent>
      {isAuthenticated ? <Footer /> : <CustomerFooter />}
    </>
  );
}

function AppWrapper() {
  const { username } = useParams();

  return <AppContent username={username} />;
}

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<UsernamePrompt />} />
        <Route path="/:username/*" element={<AppWrapper />} />
      </Routes>
    </Router>
  );
}

export default App;
