import React, { useState } from 'react';
import {
  Container, Button, Form, FormGroup, Label, Input, ListGroup, ListGroupItem
} from 'reactstrap';
import styled from 'styled-components';
import CustomerFooter from './CustomerFooter';
import { getOrdersByPhoneNumber } from './api';

// Styled Components
const StyledContainer = styled(Container)`
  padding-top: 3rem;
  padding-bottom: 3rem;
  background: #f8f9fa;
`;

const SectionTitle = styled.h2`
  text-align: center;
  margin-bottom: 2rem;
  color: #333;
`;

const SearchForm = styled(Form)`
  max-width: 600px;
  margin: 0 auto;
  background: #ffffff;
  padding: 2rem;
  border-radius: 8px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
`;

const ErrorMessage = styled.p`
  color: #dc3545;
  text-align: center;
`;

const OrderCard = styled.div`
  background: #ffffff;
  border: 1px solid #dee2e6;
  border-radius: 8px;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
`;

const OrderTitle = styled.h4`
  margin: 0;
  color: #007bff;
`;

const OrderStatus = styled.p`
  font-weight: bold;
  margin: 0.5rem 0;
`;

const OrderItem = styled(ListGroupItem)`
  background: #f8f9fa;
  border: none;
`;

const NoteItem = styled(ListGroupItem)`
  background: #e9ecef;
  border: none;
  margin-top: 0.5rem;
  font-style: italic;
  font-size: 0.9rem;
`;

// Helper function to validate Australian phone number
const validatePhoneNumber = (phone) => {
  const auPhoneNumberRegex = /^(\+61|0)[2-478]( ?\d){8}$/;
  return auPhoneNumberRegex.test(phone);
};

// Components
const OrderTracking = (params) => {
  const userId = params.userId;
  const [phoneNumber, setPhoneNumber] = useState('');
  const [orders, setOrders] = useState([]);
  const [error, setError] = useState(null);
  const [visibleNotes, setVisibleNotes] = useState({}); // State to manage visible notes

  const handleSearch = async () => {
    if (!validatePhoneNumber(phoneNumber)) {
      setError('Please enter a valid Australian phone number.');
      return;
    }

    try {
      const fetchedOrders = await getOrdersByPhoneNumber(userId, phoneNumber);
      if (fetchedOrders.length > 0) {
        setOrders(fetchedOrders);
        setError(null);
      } else {
        setOrders([]);
        setError('No orders found for this phone number.');
      }
    } catch (err) {
      setError('Error fetching orders. Please try again later.');
    }
  };

  const toggleNotesVisibility = (orderId) => {
    setVisibleNotes((prevState) => ({
      ...prevState,
      [orderId]: !prevState[orderId],
    }));
  };

  return (
    <>
      <StyledContainer>
        <SectionTitle>Track Your Order</SectionTitle>
        <SearchForm>
          <FormGroup>
            <Label for="phoneNumber">Phone Number</Label>
            <Input
              type="text"
              id="phoneNumber"
              name="phoneNumber"
              value={phoneNumber}
              onChange={(e) => setPhoneNumber(e.target.value)}
              required
              placeholder="Enter your phone number"
              invalid={phoneNumber && !validatePhoneNumber(phoneNumber)}
            />
          </FormGroup>
          <Button color="primary" onClick={handleSearch} block>
            Track Order
          </Button>
        </SearchForm>

        {error && <ErrorMessage>{error}</ErrorMessage>}

        {orders.length > 0 && (
          <>
            <SectionTitle>Order History</SectionTitle>
            {orders.map((order) => (
              <OrderCard key={order.id}>
                <OrderTitle>Order #{order.invoiceNumber}</OrderTitle>
                <OrderStatus>Status: {order.status}</OrderStatus>
                <ListGroup>
                  {order.cart.map((item) => (
                    <OrderItem key={item.id}>
                      {item.name} - Quantity: {item.quantity} - Price: ₹{item.price.toFixed(2)}
                    </OrderItem>
                  ))}
                </ListGroup>
                {Array.isArray(order.notes) && order.notes.length > 0 && (
                  <>
                    <Button
                      color="secondary"
                      onClick={() => toggleNotesVisibility(order.id)}
                      style={{ marginTop: '1rem' }}
                    >
                      {visibleNotes[order.id] ? 'Hide Notes' : 'See Notes'}
                    </Button>
                    {visibleNotes[order.id] && (
                      <ListGroup className="mt-3">
                        {order.notes.map((note, index) => (
                          <NoteItem key={index}>
                            {note.timestamp}: {note.text}
                          </NoteItem>
                        ))}
                      </ListGroup>
                    )}
                  </>
                )}
              </OrderCard>
            ))}
          </>
        )}
      </StyledContainer>
      <CustomerFooter />
    </>
  );
};

export default OrderTracking;
