const STORAGE = localStorage;

// Helper function to generate a unique ID
export const generateUniqueId = () => {
  return '_' + Math.random().toString(36).substr(2, 9);
};

// Cache settings
const CACHE_TTL = 1000; // Cache TTL set to 60 seconds (60000 milliseconds)
let cachedCart = null;
let cachedProducts = null;
let cachedOrders = null;

let cartFetchTime = 0;
let productsFetchTime = 0;
let ordersFetchTime = 0;

// General function to get data by key
export const getData = (key) => {
  const data = STORAGE.getItem(key);
  console.log(`getData called for key: ${key}, returning:`, data);
  return data ? JSON.parse(data) : [];
};

// General function to set data by key
export const setData = (key, data) => {
  console.log(`setData called for key: ${key}, setting:`, data);
  STORAGE.setItem(key, JSON.stringify(data));
  console.log('Data successfully saved for key:', key);
};

// Specific function to clear all local storage
export const clearLocalStorage = () => {
  console.log('clearLocalStorage called');
  STORAGE.clear();
  console.log('All local storage cleared');
};

// Specific function to load cart data
export const loadCart = () => {
  const currentTime = Date.now();
  if (cachedCart && (currentTime - cartFetchTime < CACHE_TTL)) {
    console.log('Returning cached cart');
    return cachedCart;
  }

  const cart = getData('cart');
  cachedCart = cart;
  cartFetchTime = Date.now();

  console.log('Cart loaded:', cart);
  return cart;
};

// Specific function to save cart data
export const saveCart = (cart) => {
  cachedCart = null; // Invalidate the cache
  cartFetchTime = 0;

  setData('cart', cart);
  console.log('Cart data saved:', cart);
};

const BASE_URL = process.env.REACT_APP_BASE_URL;

// General function to handle API responses
const handleResponse = async (response) => {
  if (!response.ok) {
    const error = await response.json();
    throw new Error(error.message || 'Something went wrong');
  }
  return await response.json(); // Parse the response as JSON
};

// Specific function to load products from the backend
export const loadProducts = async (userId) => {
  const currentTime = Date.now();
  if (cachedProducts && (currentTime - productsFetchTime < CACHE_TTL)) {
    console.log('Returning cached products');
    return cachedProducts;
  }

  console.log('Loading products');
  try {
    const response = await fetch(`${BASE_URL}/online-products/${userId}`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      },
    });
    const products = await handleResponse(response);
    
    cachedProducts = Array.isArray(products) ? products : [];
    productsFetchTime = Date.now();

    console.log(products);
    return cachedProducts;
  } catch (error) {
    console.error('Error loading products:', error);
    return [];
  }
};

// Specific function to get orders by phone number
export const getOrdersByPhoneNumber = async (userId, phoneNumber) => {
  const currentTime = Date.now();
  if (cachedOrders && (currentTime - ordersFetchTime < CACHE_TTL)) {
    console.log('Returning cached orders');
    return cachedOrders;
  }

  try {
    const response = await fetch(`${BASE_URL}/orders/byPhone/${userId}/${phoneNumber}`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'user_id': userId, // Adding the dynamic user_id in the header
      },
    });
    const data = await handleResponse(response);
    
    cachedOrders = data;
    ordersFetchTime = Date.now();

    console.log(`Orders loaded for phone number ${phoneNumber}:`, data);
    return cachedOrders;
  } catch (error) {
    console.error(`Error loading orders for phone number ${phoneNumber}:`, error);
    throw new Error('Failed to load orders by phone number');
  }
};
