const finalizeEndSession = async () => {
  if (!finalCashCount) {
    alert("Please enter the final cash count.");
    return;
  }

  const totalSales = sessionTransactions
    .filter(txn => txn.txn_type === 'sale')
    .reduce((sum, txn) => sum + parseFloat(txn.total), 0);

  const totalRefunds = sessionTransactions
    .filter(txn => txn.txn_type === 'refund')
    .reduce((sum, txn) => sum + parseFloat(txn.total), 0);

  const netSales = totalSales - totalRefunds;

  const expectedCash = parseFloat(initialCashCount) +
    sessionTransactions.reduce((sum, txn) => txn.payments
      .filter(p => p.method === 'cash')
      .reduce((s, p) => s + parseFloat(p.amount), 0), 0);

  const discrepancy = parseFloat(finalCashCount) - expectedCash;

  const sessionEndData = {
    final_cash: parseFloat(finalCashCount),
    end_time: new Date().toISOString(),
    transactions: sessionTransactions,
    total_sales: totalSales,
    total_refunds: totalRefunds,
    net_sales: netSales,
    expected_cash: expectedCash,
    discrepancy: discrepancy,
  };

  try {
    const response = await endSession(sessionEndData);
    alert("Session ended successfully.");
    console.log('Session ended:', response);
    setIsBlurred(true); // Blur UI after ending session
    setEndSessionModal(false);
    setSessionStartTime(null);
    setInitialCashCount('');
    setFinalCashCount('');
    setSessionTransactions([]);
    setCashierName('');
    setTransactionIds([]); // Clear transaction IDs
    setStartSessionModal(true); // Prompt to start a new session
  } catch (error) {
    console.error("Failed to end session:", error);
  }
};


  
