import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import styled from 'styled-components';
import { Nav, NavItem, Button } from 'reactstrap';
import {
  FaCashRegister,
  FaBoxOpen,
  FaChartLine,
  FaClipboardList,
  FaUser,
  FaSignOutAlt,
  FaCog,
  FaTruck,
  FaBars,  // Hamburger icon
  FaArrowLeft,  // Collapse icon
  FaArrowRight  // Expand icon
} from 'react-icons/fa';

const StyledNav = styled(Nav)`
  background: linear-gradient(135deg, #003459, #007ea7);
  height: 100vh;
  color: white;
  padding: 20px;
  position: fixed;
  top: 0;
  bottom: 0;
  width: ${({ isOpen }) => (isOpen ? '220px' : '60px')};  /* Reduced width when closed */
  overflow-y: hidden;  /* Disable scrolling in sidebar */
  box-shadow: 2px 0 5px rgba(0, 0, 0, 0.3);
  z-index: 1000;
  font-family: 'Montserrat', sans-serif;
  transition: width 0.3s ease-in-out, transform 0.3s ease-in-out;

  @media (max-width: 768px) {
    transform: ${({ isOpen }) => (isOpen ? 'translateX(0)' : 'translateX(-100%)')};
    width: ${({ isOpen }) => (isOpen ? '100%' : '60px')};  /* Full width when open, icon width when closed */
  }
`;

const SidebarToggleButton = styled.div`
  position: fixed;
  top: 10px;
  left: ${({ isOpen }) => (isOpen ? '220px' : '60px')};  /* Adjust position based on sidebar state */
  z-index: 1100;
  font-size: 2rem;
  color: white;
  cursor: pointer;
  transition: left 0.3s ease-in-out;

  @media (max-width: 768px) {
    left: 10px;
  }
`;

const StyledNavItem = styled(NavItem)`
  margin: 15px 0;
  font-size: 1.1rem;
  width: 100%;  /* Ensure nav items take up full width */
  display: flex;
  align-items: center;
  justify-content: ${({ isOpen }) => (isOpen ? 'flex-start' : 'center')};  /* Align content based on sidebar state */
  
  a {
    color: white;
    text-decoration: none;
    display: flex;
    align-items: center;
    justify-content: ${({ isOpen }) => (isOpen ? 'flex-start' : 'center')};  /* Center icons when closed */
    padding: ${({ isOpen }) => (isOpen ? '10px 15px' : '10px 0')};  /* Adjust padding based on sidebar state */
    width: 100%;  /* Ensure the link takes up the full width */
    border-radius: 8px;
    transition: background-color 0.3s ease-in-out, color 0.3s ease-in-out;
    background: linear-gradient(45deg, #007ea7, #003459);
    color: white;
    font-weight: ${({ isOpen }) => (isOpen ? '500' : '400')};  /* Adjust font weight based on sidebar state */

    svg {
      margin-right: ${({ isOpen }) => (isOpen ? '10px' : '0')};  /* Remove margin when closed */
    }

    &:hover {
      color: #ffffff;
      background-color: #00507d;
    }

    &.active {
      background: linear-gradient(45deg, #007ea7, #00507d);
      color: #ffffff;
      font-weight: bold;
    }
  }
`;

const StyledButton = styled(Button)`
  width: 100%;
  margin: 10px 0;
  background: linear-gradient(45deg, #007ea7, #003459);
  border: none;
  color: white;
  font-weight: 500;
  border-radius: 8px;

  &:hover {
    background: linear-gradient(45deg, #00507d, #00293c);
    color: #ffffff;
  }

  svg {
    margin-right: 10px;
  }
`;

const Sidebar = ({ handleLogout, toggleSidebar, isOpen, username }) => {
  console.log(username,'in sidebar')
  const handleToggle = () => {
    toggleSidebar(!isOpen);  // Pass the new state back to App component
  };
  
  return (
    <>
      <SidebarToggleButton isOpen={isOpen} onClick={handleToggle}>
        {isOpen ? <FaArrowLeft /> : <FaArrowRight />}
      </SidebarToggleButton>
      <StyledNav isOpen={isOpen} vertical>
        <StyledNavItem isOpen={isOpen}>
          <Link to={`/${username}/pos`}>
            <FaCashRegister /> {isOpen && 'POS'}
          </Link>
        </StyledNavItem>
        <StyledNavItem isOpen={isOpen}>
          <Link to={`/${username}/online-order-management`}>
            <FaTruck /> {isOpen && 'Online Order Management'}
          </Link>
        </StyledNavItem>
        <StyledNavItem isOpen={isOpen}>
          <Link to={`/${username}/manage-products`}>
            <FaBoxOpen /> {isOpen && 'Manage Products'}
          </Link>
        </StyledNavItem>
        <StyledNavItem isOpen={isOpen}>
          <Link to={`/${username}/inventory-management`}>
            <FaClipboardList /> {isOpen && 'Inventory Management'}
          </Link>
        </StyledNavItem>
        {/* New Tab for Suppliers */}
        <StyledNavItem isOpen={isOpen}>
          <Link to={`/${username}/suppliers`}>
            <FaTruck /> {isOpen && 'Suppliers'}
          </Link>
        </StyledNavItem>
        <StyledNavItem isOpen={isOpen}>
          <Link to={`/${username}/sales-history`}>
            <FaChartLine /> {isOpen && 'Sales History'}
          </Link>
        </StyledNavItem>
        <StyledNavItem isOpen={isOpen}>
          <Link to={`/${username}/sales-analytics`}>
            <FaChartLine /> {isOpen && 'Sales Analytics'}
          </Link>
        </StyledNavItem>
        <StyledNavItem isOpen={isOpen}>
          <Link to={`/${username}/profile`}>
            <FaUser /> {isOpen && 'Profile'}
          </Link>
        </StyledNavItem>
        <StyledNavItem isOpen={isOpen}>
          <Link to={`/${username}/settings`}>
            <FaCog /> {isOpen && 'Settings'}
          </Link>
        </StyledNavItem>

        <StyledNavItem isOpen={isOpen}>
          <StyledButton color="danger" onClick={handleLogout}>
            <FaSignOutAlt /> {isOpen && 'Logout'}
          </StyledButton>
        </StyledNavItem>
      </StyledNav>
    </>
  );
};

export default Sidebar;
