import React, { useState } from 'react';
import { Container, Form, FormGroup, Label, Input, Button } from 'reactstrap';
import styled from 'styled-components';

// Styled components
const CheckoutContainer = styled(Container)`
  padding: 2rem;
  max-width: 600px;
  background: linear-gradient(135deg, #00C4CC, #008C95);
  border-radius: 12px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  color: white;
`;

const Header = styled.h2`
  text-align: center;
  margin-bottom: 1.5rem;
  font-family: 'Arial', sans-serif;
`;

const StyledFormGroup = styled(FormGroup)`
  margin-bottom: 1rem;
`;

const StyledLabel = styled(Label)`
  font-weight: bold;
  margin-bottom: 0.5rem;
`;

const StyledInput = styled(Input)`
  border-radius: 8px;
  border: 1px solid #ddd;
  padding: 0.75rem;
`;

const StyledButton = styled(Button)`
  background-color: #28a745;
  border-color: #28a745;
  width: 100%;
  padding: 0.75rem;
  font-size: 1.1rem;
  border-radius: 8px;
  &:hover {
    background-color: #218838;
    border-color: #1e7e34;
  }
`;

const Checkout = ({ cart, placeOrder }) => {
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    address: '',
  });

  const handleInputChange = (e) => {
    const { id, value } = e.target;
    setFormData((prevFormData) => ({
      ...prevFormData,
      [id]: value,
    }));
  };

  const handleOrder = () => {
    if (placeOrder) {
      placeOrder({ ...formData, cart });
    } else {
      console.error("placeOrder function is not defined");
    }
  };

  return (
    <CheckoutContainer>
      <Header>Checkout</Header>
      <Form>
        <StyledFormGroup>
          <StyledLabel for="name">Name</StyledLabel>
          <StyledInput
            type="text"
            id="name"
            value={formData.name}
            onChange={handleInputChange}
            placeholder="Enter your full name"
          />
        </StyledFormGroup>
        <StyledFormGroup>
          <StyledLabel for="phone">Phone Number</StyledLabel>
          <StyledInput
            type="text"
            id="phone"
            value={formData.phone}
            onChange={handleInputChange}
            placeholder="Enter your phone number"
          />
        </StyledFormGroup>
        <StyledFormGroup>
          <StyledLabel for="address">Address</StyledLabel>
          <StyledInput
            type="text"
            id="address"
            value={formData.address}
            onChange={handleInputChange}
            placeholder="Enter your delivery address"
          />
        </StyledFormGroup>
        <StyledButton color="success" onClick={handleOrder}>
          Place Order
        </StyledButton>
      </Form>
    </CheckoutContainer>
  );
};

export default Checkout;
