import React, { useState, useEffect } from 'react';
import {
  Button, Form, Input, Row, Col, Modal, Tree, Card, Space, Select, message, Dropdown, Menu, Popconfirm, Tabs
} from 'antd';
import { FolderOpenOutlined, FileOutlined, PlusOutlined, DownOutlined, DeleteOutlined, SaveOutlined } from '@ant-design/icons';
import styled from 'styled-components';
import { loadSettings, saveSettings, loadProducts } from '../auth/api';
import currencyFormatter from 'currency-formatter';

const { TabPane } = Tabs;

const StyledContainer = styled.div`
  padding: 2rem;
  padding-top: 0rem;
  background-color: #f5f5f5;
  min-height: calc(100vh - 40px - 100px);
  max-height: calc(100vh - 40px - 100px);
`;

const POSPreviewContainer = styled.div`
  padding: 1rem;
  border: 1px solid #ccc;
  border-radius: 5px;
  margin-top: 1rem;
  background-color: #fff;
`;

const GridContainer = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 10px;
`;

const StyledCard = styled(Card)`
  margin-bottom: 10px;
  transition: transform 0.2s, box-shadow 0.2s;
  &:hover {
    transform: scale(1.05);
    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2);
  }
`;

const CardImageBackground = styled.div`
  background-image: url(${(props) => props.image});
  background-size: cover;
  background-position: center;
  height: 100px;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: flex-end;
  border-radius: 5px 5px 0 0;
`;

const ProductDetails = styled.div`
  background-color: rgba(0, 0, 0, 0.6);
  color: white;
  width: 100%;
  text-align: center;
  padding: 5px 0;
  font-size: 0.8rem;
  border-radius: 0 0 5px 5px;
`;

const GradientButton = styled(Button)`
  background: ${(props) =>
    props.color === 'primary'
      ? 'linear-gradient(45deg, #1d8cf8, #3358f4)'
      : props.color === 'info'
      ? 'linear-gradient(45deg, #11cdef, #1171ef)'
      : props.color === 'success'
      ? 'linear-gradient(45deg, #00d97e, #00b856)'
      : props.color === 'danger'
      ? 'linear-gradient(45deg, #f5365c, #e0244a)'
      : props.color === 'secondary'
      ? 'linear-gradient(45deg, #8898aa, #667d8b)'
      : 'linear-gradient(45deg, #1d8cf8, #3358f4)'};
  border: none;
  color: white;
  padding: 5px 10px;
  margin-right: 5px;
  margin-bottom: 5px;
  font-size: 0.8rem;
  &:hover {
    opacity: 0.9;
  }
`;

const Settings = () => {
  const [settings, setSettings] = useState({
    cameraEnabled: false,
    selectedCamera: '',
    barcodeScannerEnabled: false,
    paymentEftposEnabled: false,
    categories: [],
    layoutPreviews: [],
  });
  const [cameras, setCameras] = useState([]);
  const [products, setProducts] = useState([]);
  const [modalVisible, setModalVisible] = useState(false);
  const [modalType, setModalType] = useState('category');
  const [currentCategory, setCurrentCategory] = useState(null);
  const [categoryTree, setCategoryTree] = useState([]);
  const [newItemId, setNewItemId] = useState('');
  const [layoutName, setLayoutName] = useState(''); // For saving layouts
  const [selectedLayout, setSelectedLayout] = useState(null); // For loading layouts
  const [onlinePOSLayout, setOnlinePOSLayout] = useState(null);
  const [internalPOSLayout, setInternalPOSLayout] = useState(null);

  

  useEffect(() => {
    const fetchSettings = async () => {
      const savedSettings = await loadSettings();
      if (!savedSettings.categories || savedSettings.categories.length === 0) {
        const rootCategory = {
          id: 'root',
          name: 'Root',
          children: [],
          products: [],
        };
        savedSettings.categories = [rootCategory];
      }
      setSettings({
        ...savedSettings,
        categories: savedSettings.categories || [],
        layoutPreviews: savedSettings.layoutPreviews || [],
      });
      setCategoryTree(formatCategories(savedSettings.categories || []));
      setSelectedLayout(savedSettings.layoutPreviews?.[0]?.id || null);
      loadCameras();
      fetchProducts();
    };

    fetchSettings();
  }, []);

  const loadCameras = async () => {
    try {
      const devices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = devices.filter(device => device.kind === 'videoinput');
      setCameras(videoDevices);
    } catch (error) {
      console.error('Error fetching cameras:', error);
    }
  };

  const fetchProducts = async () => {
    const existingProducts = await loadProducts();
    setProducts(existingProducts || []);
  };

  const formatCategories = (categories) => {
    return categories.map(category => ({
      title: category.name,
      key: category.id,
      isLeaf: false,
      children: formatCategories(category.children || []).concat(
        (category.products || []).map(product => ({
          title: `${product.name} - $${product.price}`,
          key: product.id,
          isLeaf: true,
          product,
          icon: <FileOutlined />
        }))
      ),
      icon: <FolderOpenOutlined />,
    }));
  };

  const handleAddCategory = () => {
    if (!newItemId.trim()) {
      message.error('Category name cannot be empty');
      return;
    }

    const newCategory = {
      id: Date.now().toString(),
      name: newItemId,
      children: [],
      products: [],
    };

    const updatedCategories = [...settings.categories];
    if (currentCategory) {
      const category = findCategory(updatedCategories, currentCategory.key);
      category.children.push(newCategory);
    } else {
      updatedCategories[0].children.push(newCategory); // Add to root category
    }

    setSettings({ ...settings, categories: updatedCategories });
    setCategoryTree(formatCategories(updatedCategories));
    setNewItemId('');
    setModalVisible(false);
    saveSettings({ ...settings, categories: updatedCategories });
  };

  const handleAddProduct = (productId) => {
    let productToAdd = products.find(product => product.id.toString() === productId);

    if (!productToAdd) {
      message.error('Please select a valid product');
      return;
    }
    //productToAdd = {'id': productId, 'name':productToAdd.name, 'price':productToAdd.price}; // to remove the unnacessary size and data just store the id

    const updatedCategories = [...settings.categories];
    if (currentCategory) {
      const category = findCategory(updatedCategories, currentCategory.key);
      category.products.push(productToAdd);
    } else {
      message.error('Please select a category to add the product to');
    }

    setSettings({ ...settings, categories: updatedCategories });
    setCategoryTree(formatCategories(updatedCategories));
    setModalVisible(false);
    saveSettings({ ...settings, categories: updatedCategories });
  };

  const findCategory = (categories, key) => {
    for (const category of categories) {
      if (category.id === key) return category;
      if (category.children) {
        const found = findCategory(category.children, key);
        if (found) return found;
      }
    }
    return null;
  };

  const handleDeleteCategory = (key) => {
    const updatedCategories = deleteCategory(settings.categories, key);
    setSettings({ ...settings, categories: updatedCategories });
    setCategoryTree(formatCategories(updatedCategories));
    saveSettings({ ...settings, categories: updatedCategories });
  };

  const deleteCategory = (categories, key) => {
    return categories.filter(category => {
      if (category.id === key) return false;
      if (category.children) {
        category.children = deleteCategory(category.children, key);
      }
      return true;
    });
  };

  const handleDeleteProduct = (productKey) => {
    const updatedCategories = deleteProduct(settings.categories, productKey);
    setSettings({ ...settings, categories: updatedCategories });
    setCategoryTree(formatCategories(updatedCategories));
    saveSettings({ ...settings, categories: updatedCategories });
  };

  const deleteProduct = (categories, productKey) => {
    return categories.map(category => {
      category.products = category.products.filter(product => product.id !== productKey);
      if (category.children) {
        category.children = deleteProduct(category.children, productKey);
      }
      return category;
    });
  };

  const renderPreview = (category) => {
    if (!category || !category.children || category.children.length === 0) {
      return <p>No items to display</p>;
    }

    return (
      <GridContainer>
        {category.children.map(item => (
          item.isLeaf ? (
            <StyledCard
              key={item.key}
              hoverable
              cover={<CardImageBackground image={item.product.frontImage || 'https://via.placeholder.com/150'} />}
              actions={[
                <Popconfirm title="Are you sure delete this product?" onConfirm={() => handleDeleteProduct(item.key)}>
                  <GradientButton color="danger">
                    <DeleteOutlined /> Delete
                  </GradientButton>
                </Popconfirm>,
              ]}
            >
              <ProductDetails>
                <h6>{item.product.name}</h6>
                <p>${item.product.price}</p>
              </ProductDetails>
            </StyledCard>
          ) : (
            <StyledCard key={item.key} onClick={() => setCurrentCategory(item)}>
              <FolderOpenOutlined /> {item.title}
            </StyledCard>
          )
        ))}
      </GridContainer>
    );
  };

  const menu = (
    <Menu onClick={({ key }) => handleAddProduct(key)}>
      {products.map(product => (
        <Menu.Item key={product.id}>
          {product.name}
        </Menu.Item>
      ))}
    </Menu>
  );

 function getAllLocalStorageData() {
    const localStorageKeys = Object.keys(localStorage);
    const localStorageData = {};
  
    localStorageKeys.forEach(key => {
      localStorageData[key] = localStorage.getItem(key);
    });
  
    return localStorageData;
  }

  function downloadLocalStorageData() {
    const data = getAllLocalStorageData();
    const jsonData = JSON.stringify(data, null, 2); // Format the JSON data
  
    const blob = new Blob([jsonData], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
  
    const a = document.createElement('a');
    a.href = url;
    a.download = Date.now()+'local_storage_data.json';
    a.click();
  
    URL.revokeObjectURL(url);
  }

  const handleSaveSettings = () => {
    saveSettings(settings);
    message.success('Settings saved successfully!');
   
  };

  const handleDownloadSettings = () => {
    message.success('Settings saved successfully!');
    // Download local storage data after saving
    downloadLocalStorageData();
  };

  const handleImportData = () => {
  const fileInput = document.getElementById('fileInput');
  const file = fileInput.files[0];

  
  if (file) { // Check if a file is selected
    const reader = new FileReader();
    reader.onload = (event) => {
      const importedData = JSON.parse(event.target.result);

      localStorage.clear();

      // Iterate over the imported data and update local storage
      for (const key in importedData) {
        localStorage.setItem(key, importedData[key]);
      }

      // Optionally, display a success message or refresh the page
      alert('Data imported successfully!');
      // window.location.reload();
    };
    reader.readAsText(file);
  } else {
    // Handle the case where no file is selected
    alert('Please select a file to import.');
  }
 
  };
  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setSettings({
      ...settings,
      [name]: type === 'checkbox' ? checked : value,
    });
  };

  const saveLayout = () => {
    if (!layoutName.trim()) {
      message.error('Please enter a layout name');
      return;
    }

    // Check if we are updating an existing layout
    const existingLayoutIndex = settings.layoutPreviews.findIndex(layout => layout.id === selectedLayout);

    if (existingLayoutIndex >= 0) {
      const updatedLayout = {
        id: selectedLayout,
        name: layoutName,
        categories: settings.categories,
      };

      const updatedSettings = { ...settings };
      updatedSettings.layoutPreviews[existingLayoutIndex] = updatedLayout;

      setSettings(updatedSettings);
      saveSettings(updatedSettings);
      message.success('Layout updated successfully!');
    } else {
      // Saving a new layout
      const newLayout = {
        id: Date.now().toString(),
        name: layoutName,
        categories: settings.categories,
      };

      const updatedSettings = {
        ...settings,
        layoutPreviews: [...settings.layoutPreviews, newLayout],
      };

      setSettings(updatedSettings);
      saveSettings(updatedSettings);
      message.success('Layout saved successfully!');
    }

    setLayoutName('');  // Clear the input after saving
  };

  const loadLayout = (layoutId) => {
    const selectedLayout = settings.layoutPreviews.find(layout => layout.id === layoutId);
    if (selectedLayout) {
      setSettings(prevSettings => ({
        ...prevSettings,
        categories: selectedLayout.categories,
      }));
      setCategoryTree(formatCategories(selectedLayout.categories));
      message.success('Layout loaded successfully!');
    } else {
      message.error('Failed to load layout.');
    }
  };

  const deleteLayout = (layoutId) => {
    const updatedSettings = {
      ...settings,
      layoutPreviews: settings.layoutPreviews.filter(layout => layout.id !== layoutId),
    };

    setSettings(updatedSettings);
    saveSettings(updatedSettings);
    setSelectedLayout(null); // Clear the selected layout
    message.success('Layout deleted successfully!');
  };

  const saveInternalPOSLayout = () => {
    if (!internalPOSLayout) {
      message.error('Please select a layout for the Inbuilt POS System');
      return;
    }

    const updatedSettings = {
      ...settings,
      POS1: internalPOSLayout,
    };

    setSettings(updatedSettings);
    saveSettings(updatedSettings);
    message.success('Inbuilt POS System Layout saved successfully as POS1!');
  };

  const saveCustomerPOSLayout = () => {
    if (!onlinePOSLayout) {
      message.error('Please select a layout for the Customer Side');
      return;
    }

    const updatedSettings = {
      ...settings,
      POS2: onlinePOSLayout,
    };

    setSettings(updatedSettings);
    saveSettings(updatedSettings);
    message.success('Customer Side Layout saved successfully as POS2!');
  };

  return (
    <StyledContainer>
      <Tabs>
        <TabPane tab="Data Management" key="1">
          <Row>
            <Col>
             
              <h3>Import/Export Data</h3>
              <Button onClick={handleImportData} block>
                Import Data
              </Button>
              
              <input
                id="fileInput"
                type="file"
                style={{  }}
                onChange={handleInputChange}
              />
             
              
              <Button onClick={handleDownloadSettings} block>
                Export Data
              </Button>
            </Col>
          </Row>
        </TabPane>

        <TabPane tab="Device Management" key="2">
          <Form>
            <Form.Item>
              <Input
                type="checkbox"
                name="cameraEnabled"
                checked={settings.cameraEnabled}
                onChange={handleInputChange}
              /> Enable Camera
            </Form.Item>
            {settings.cameraEnabled && (
              <Form.Item label="Select Camera">
                <Select
                  name="selectedCamera"
                  value={settings.selectedCamera}
                  onChange={(value) => handleInputChange({ target: { name: 'selectedCamera', value } })}
                >
                  {cameras.map((camera) => (
                    <Select.Option key={camera.deviceId} value={camera.deviceId}>
                      {camera.label || `Camera ${camera.deviceId}`}
                    </Select.Option>
                  ))}
                </Select>
              </Form.Item>
            )}
            <Form.Item>
              <Input
                type="checkbox"
                name="barcodeScannerEnabled"
                checked={settings.barcodeScannerEnabled}
                onChange={handleInputChange}
              /> Enable Barcode Scanner
            </Form.Item>
            <Form.Item>
              <Input
                type="checkbox"
                name="paymentEftposEnabled"
                checked={settings.paymentEftposEnabled}
                onChange={handleInputChange}
              /> Enable EFTPOS Payment
            </Form.Item>
            <Button onClick={handleSaveSettings}>
              Save Settings
            </Button>
          </Form>
        </TabPane>

        <TabPane tab="Category Management" key="3">
          <Row gutter={16}>
            <Col span={8}>
              <Space direction="vertical" style={{ width: '100%' }}>
                <Button icon={<PlusOutlined />} onClick={() => { setModalType('category'); setModalVisible(true); }}>
                  Add Category
                </Button>
                <Dropdown overlay={menu}>
                  <Button icon={<PlusOutlined />}>
                    Add Product <DownOutlined />
                  </Button>
                </Dropdown>
                <Tree
                  treeData={categoryTree}
                  onSelect={(keys, event) => setCurrentCategory(event.node)}
                  showLine
                  defaultExpandAll
                  style={{ marginTop: 20 }}
                />

                <Form.Item label="Save Current Layout">
                  <Input
                    value={layoutName}
                    onChange={(e) => setLayoutName(e.target.value)}
                    placeholder="Enter layout name"
                    style={{ marginBottom: '10px' }}
                  />
                  <Button onClick={saveLayout} icon={<SaveOutlined />}>
                    Save Layout
                  </Button>
                </Form.Item>

                <Form.Item label="Load Saved Layout">
                  <Select
                    style={{ width: '100%', marginTop: 20 }}
                    value={selectedLayout}
                    onChange={setSelectedLayout}
                  >
                    {settings.layoutPreviews.map(layout => (
                      <Select.Option key={layout.id} value={layout.id}>
                        {layout.name}
                      </Select.Option>
                    ))}
                  </Select>
                  <Button
                    onClick={() => loadLayout(selectedLayout)}
                    style={{ marginTop: 10 }}
                    icon={<FolderOpenOutlined />}
                  >
                    Load Layout
                  </Button>
                  <Popconfirm
                    title="Are you sure to delete this layout?"
                    onConfirm={() => deleteLayout(selectedLayout)}
                    okText="Yes"
                    cancelText="No"
                  >
                    <Button
                      danger
                      style={{ marginTop: 10 }}
                      icon={<DeleteOutlined />}
                    >
                      Delete Layout
                    </Button>
                  </Popconfirm>
                </Form.Item>
              </Space>
            </Col>
            <Col span={16}>
              <POSPreviewContainer>
                <h3>Preview</h3>
                {renderPreview(currentCategory || settings.categories[0])}
              </POSPreviewContainer>
            </Col>
          </Row>
        </TabPane>

        <TabPane tab="POS Layout Preview" key="4">
          <Row gutter={16}>
            <Col span={24}>
              <h3>Customer Side Preview</h3>
              <Select
                value={onlinePOSLayout}
                onChange={(value) => setOnlinePOSLayout(value)}
                style={{ width: '100%', marginBottom: '20px' }}
              >
                {settings.layoutPreviews.map(layout => (
                  <Select.Option key={layout.id} value={layout.id}>
                    {layout.name}
                  </Select.Option>
                ))}
              </Select>
              <POSPreviewContainer>
                {renderPreview(onlinePOSLayout ? settings.layoutPreviews.find(layout => layout.id === onlinePOSLayout)?.categories[0] : null)}
              </POSPreviewContainer>
              <Button onClick={saveCustomerPOSLayout} type="primary" icon={<SaveOutlined />} style={{ marginTop: '20px' }}>
                Save as POS2
              </Button>
            </Col>
            <Col span={24}>
              <h3>Inbuilt POS System Preview</h3>
              <Select
                value={internalPOSLayout}
                onChange={(value) => setInternalPOSLayout(value)}
                style={{ width: '100%', marginBottom: '20px' }}
              >
                {settings.layoutPreviews.map(layout => (
                  <Select.Option key={layout.id} value={layout.id}>
                    {layout.name}
                  </Select.Option>
                ))}
              </Select>
              <POSPreviewContainer>
                {renderPreview(internalPOSLayout ? settings.layoutPreviews.find(layout => layout.id === internalPOSLayout)?.categories[0] : null)}
              </POSPreviewContainer>
              <Button onClick={saveInternalPOSLayout} type="primary" icon={<SaveOutlined />} style={{ marginTop: '20px' }}>
                Save as POS1
              </Button>
            </Col>
          </Row>
        </TabPane>

      </Tabs>

      <Modal
        visible={modalVisible}
        title={modalType === 'category' ? 'Add Category' : 'Add Product'}
        onCancel={() => setModalVisible(false)}
        onOk={modalType === 'category' ? handleAddCategory : () => handleAddProduct(newItemId)}
      >
        {modalType === 'category' ? (
          <Form.Item label="Category Name">
            <Input value={newItemId} onChange={e => setNewItemId(e.target.value)} />
          </Form.Item>
        ) : (
          <Form.Item label="Select Product">
            <Select
              value={newItemId}
              onChange={setNewItemId}
              showSearch
              style={{ width: '100%' }}
            >
              {products.map(product => (
                <Select.Option key={product.id} value={product.id}>
                  {product.name}
                </Select.Option>
              ))}
            </Select>
          </Form.Item>
        )}
      </Modal>
    </StyledContainer>
  );
};

export default Settings;
